/* DAWAH X — ahmad, অধ্যায় 11 · খণ্ড 11 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][11]=[[2001,2001,"","","‏ ‏حَدَّثَنَا ‏ ‏بِشْرُ بْنُ السَّرِيِّ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي نَجِيحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏مَا قَاتَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَوْمًا قَطُّ إِلَّا دَعَاهُمْ ‏","","",""],[2002,2002,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏وَرَوْحٌ ‏ ‏قَالَ ثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ بْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَيْرٍ ‏ ‏مَوْلَى ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَئِنْ عِشْتُ ‏ ‏قَالَ ‏ ‏رَوْحٌ ‏ ‏لَئِنْ سَلِمْتُ ‏ ‏إِلَى ‏ ‏قَابِلٍ ‏ ‏لَأَصُومَنَّ التَّاسِعَ ‏ ‏يَعْنِي ‏ ‏عَاشُورَاءَ ‏","","",""],[2003,2003,"","","‏ ‏حَدَّثَنِي ‏ ‏يَزِيدُ ‏ ‏قَالَ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏دَاوُدَ بْنِ الْحُصَيْنِ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قِيلَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيُّ الْأَدْيَانِ أَحَبُّ إِلَى اللَّهِ قَالَ ‏ ‏الْحَنِيفِيَّةُ ‏ ‏السَّمْحَةُ ‏","","",""],[2004,2004,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏هِشَامٌ ‏ ‏وَابْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏احْتَجَمَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ مُحْرِمٌ ‏ ‏احْتِجَامَةً ‏ ‏فِي رَأْسِهِ قَالَ ‏ ‏يَزِيدُ ‏ ‏مِنْ أَذًى كَانَ بِهِ ‏","","",""],[2005,2005,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قُبِضَ ‏ ‏النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَدِرْعُهُ ‏ ‏مَرْهُونَةٌ عِنْدَ رَجُلٍ مِنْ ‏ ‏يَهُودَ ‏ ‏عَلَى ثَلَاثِينَ ‏ ‏صَاعًا ‏ ‏مِنْ شَعِيرٍ أَخَذَهَا رِزْقًا لِعِيَالِهِ ‏","","",""],[2006,2006,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏هِشَامٌ ‏ ‏وَابْنُ جَعْفَرٍ ‏ ‏قَالَ ثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏بُعِثَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ ‏ ‏أُنْزِلَ عَلَيْهِ الْقُرْآنُ وَهُوَ ابْنُ أَرْبَعِينَ سَنَةً فَمَكَثَ ‏ ‏بِمَكَّةَ ‏ ‏ثَلَاثَ عَشْرَةَ سَنَةً ‏ ‏وَبِالْمَدِينَةِ ‏ ‏عَشْرَ سِنِينَ قَالَ فَمَاتَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ابْنُ ثَلَاثٍ وَسِتِّينَ ‏","","",""],[2007,2007,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏الْحَجَّاجُ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏مِقْسَمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُعْتِقُ مَنْ جَاءَهُ مِنْ الْعَبِيدِ قَبْلَ ‏ ‏مَوَالِيهِمْ ‏ ‏إِذَا أَسْلَمُوا وَقَدْ أَعْتَقَ يَوْمَ ‏ ‏الطَّائِفِ ‏ ‏رَجُلَيْنِ ‏","","",""],[2008,2008,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنِ ‏ ‏الْمِنْهَالِ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يُعَوِّذُ ‏ ‏حَسَنًا ‏ ‏وَحُسَيْنًا ‏ ‏يَقُولُ ‏ ‏أُعِيذُكُمَا بِكَلِمَاتِ اللَّهِ التَّامَّةِ مِنْ كُلِّ شَيْطَانٍ ‏ ‏وَهَامَّةٍ ‏ ‏وَمِنْ كُلِّ عَيْنٍ ‏ ‏لَامَّةٍ ‏ ‏وَكَانَ يَقُولُ كَانَ ‏ ‏إِبْرَاهِيمُ ‏ ‏أَبِي يُعَوِّذُ بِهِمَا ‏ ‏إِسْمَاعِيلَ ‏ ‏وَإِسْحَاقَ ‏","","",""],[2009,2009,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ بْنُ حُسَيْنٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏رَأَى رَجُلٌ رُؤْيَا فَجَاءَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ إِنِّي رَأَيْتُ كَأَنَّ ‏ ‏ظُلَّةً ‏ ‏تَنْطِفُ ‏ ‏عَسَلًا وَسَمْنًا وَكَأَنَّ النَّاسَ يَأْخُذُونَ مِنْهَا فَبَيْنَ مُسْتَكْثِرٍ وَبَيْنَ مُسْتَقِلٍّ وَبَيْنَ ذَلِكَ وَكَأَنَّ سَبَبًا مُتَّصِلًا إِلَى السَّمَاءِ ‏ ‏وقَالَ ‏ ‏يَزِيدُ ‏ ‏مَرَّةً وَكَأَنَّ ‏ ‏سَبَبًا ‏ ‏دُلِّيَ مِنْ السَّمَاءِ ‏ ‏فَجِئْتَ فَأَخَذْتَ بِهِ فَعَلَوْتَ فَعَلَّاكَ اللَّهُ ثُمَّ جَاءَ رَجُلٌ مِنْ بَعْدِكَ فَأَخَذَ بِهِ فَعَلَا فَعَلَّاهُ اللَّهُ ثُمَّ جَاءَ رَجُلٌ مِنْ بَعْدِكُمَا فَأَخَذَ بِهِ فَعَلَا فَأَعْلَاهُ اللَّهُ ثُمَّ جَاءَ رَجُلٌ مِنْ بَعْدِكُمْ فَأَخَذَ بِهِ فَقُطِعَ بِهِ ثُمَّ وُصِلَ لَهُ فَعَلَا فَأَعْلَاهُ اللَّهُ قَالَ ‏ ‏أَبُو بَكْرٍ ‏ ‏ائْذَنْ لِي يَا رَسُولَ اللَّهِ ‏ ‏فَأَعْبُرُهَا ‏ ‏لَهُ فَأَذِنَ لَهُ فَقَالَ ‏ ‏أَمَّا ‏ ‏الظُّلَّةُ ‏ ‏فَالْإِسْلَامُ وَأَمَّا الْعَسَلُ وَالسَّمْنُ فَحَلَاوَةُ الْقُرْآنِ فَبَيْنَ مُسْتَكْثِرٍ وَبَيْنَ مُسْتَقِلٍّ وَبَيْنَ ذَلِكَ وَأَمَّا ‏ ‏السَّبَبُ ‏ ‏فَمَا أَنْتَ عَلَيْهِ ‏ ‏تَعْلُو فَيُعْلِيكَ اللَّهُ ثُمَّ يَكُونُ مِنْ بَعْدِكَ رَجُلٌ عَلَى مِنْهَاجِكَ فَيَعْلُو ‏ ‏وَيُعْلِيهِ اللَّهُ ثُمَّ يَكُونُ مِنْ بَعْدِكُمَا رَجُلٌ يَأْخُذُ بِأَخْذِكُمَا فَيَعْلُو ‏ ‏فَيُعْلِيهِ اللَّهُ ثُمَّ يَكُونُ مِنْ بَعْدِكُمْ رَجُلٌ يُقْطَعُ بِهِ ثُمَّ يُوصَلُ لَهُ فَيَعْلُو ‏ ‏فَيُعْلِيهِ اللَّهُ قَالَ أَصَبْتُ يَا رَسُولَ اللَّهِ قَالَ أَصَبْتَ وَأَخْطَأْتَ قَالَ أَقْسَمْتُ يَا رَسُولَ اللَّهِ لَتُخْبِرَنِّي فَقَالَ لَا تُقْسِمْ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَجُلًا أَتَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ مَعْنَاهُ ‏","","",""],[2010,2010,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏وَمُحَمَّدٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏هَذِهِ عُمْرَةٌ اسْتَمْتَعْنَا بِهَا فَمَنْ لَمْ يَكُنْ مَعَهُ ‏ ‏هَدْيٌ ‏ ‏فَلْيَحِلَّ الْحِلَّ كُلَّهُ فَقَدْ دَخَلَتْ الْعُمْرَةُ فِي الْحَجِّ إِلَى يَوْمِ الْقِيَامَةِ ‏","","",""],[2011,2011,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ خَالِدٍ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ بْنِ عَبْدِ الرَّحْمَنِ بْنِ ذُؤَيْبٍ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَرَجَ عَلَيْهِمْ وَهُمْ جُلُوسٌ فَقَالَ ‏ ‏أَلَا أُحَدِّثُكُمْ بِخَيْرِ النَّاسِ مَنْزِلَةً فَقَالُوا بَلَى يَا رَسُولَ اللَّهِ ‏ ‏فَقَالَ رَجُلٌ مُمْسِكٌ بِعِنَانِ ‏ ‏فَرَسِهِ فِي سَبِيلِ اللَّهِ حَتَّى يَمُوتَ أَوْ يُقْتَلَ أَفَأُخْبِرُكُمْ بِالَّذِي يَلِيهِ قَالُوا نَعَمْ يَا رَسُولَ اللَّهِ قَالَ امْرُؤٌ مُعْتَزِلٌ فِي ‏ ‏شِعْبٍ ‏ ‏يُقِيمُ الصَّلَاةَ ‏ ‏وَيُؤْتِي الزَّكَاةَ وَيَعْتَزِلُ شُرُورَ النَّاسِ أَفَأُخْبِرُكُمْ بِشَرِّ النَّاسِ مَنْزِلَةً قَالُوا نَعَمْ يَا رَسُولَ اللَّهِ قَالَ الَّذِي يُسْأَلُ بِاللَّهِ وَلَا يُعْطِي بِهِ ‏","","",""],[2012,2012,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏مِسْعَرُ بْنُ كِدَامٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏أَخِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي جُلُودِ الْمَيْتَةِ قَالَ ‏ ‏إِنَّ دِبَاغَهُ قَدْ ذَهَبَ بِخَبَثِهِ ‏ ‏أَوْ رِجْسِهِ أَوْ نَجَسِهِ ‏","","",""],[2013,2013,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏مِسْعَرُ بْنُ كِدَامٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏أَخِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ ‏ ‏طَافَ ‏ ‏بِالْبَيْتِ ‏ ‏عَلَى نَاقَتِهِ ‏ ‏يَسْتَلِمُ ‏ ‏الْحَجَرَ ‏ ‏بِمِحْجَنِهِ ‏ ‏وَبَيْنَ ‏ ‏الصَّفَا ‏ ‏وَالْمَرْوَةِ ‏ ‏وَقَالَ ‏ ‏يَزِيدُ ‏ ‏مَرَّةً عَلَى ‏ ‏رَاحِلَتِهِ ‏ ‏يَسْتَلِمُ ‏ ‏الْحَجَرَ ‏","","",""],[2014,2014,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏حُسَيْنُ بْنُ ذَكْوَانَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏طَاوُسٍ ‏ ‏أَنَّ ‏ ‏ابْنَ عُمَرَ ‏ ‏وَابْنَ عَبَّاسٍ ‏ ‏رَفَعَاهُ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏لَا يَحِلُّ لِلرَّجُلِ أَنْ يُعْطِيَ الْعَطِيَّةَ فَيَرْجِعَ فِيهَا إِلَّا الْوَالِدَ فِيمَا يُعْطِي وَلَدَهُ وَمَثَلُ الَّذِي يُعْطِي الْعَطِيَّةَ فَيَرْجِعُ فِيهَا كَمَثَلِ الْكَلْبِ أَكَلَ حَتَّى إِذَا شَبِعَ قَاءَ ثُمَّ رَجَعَ فِي قَيْئِهِ ‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ الْمُعَلِّمُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏طَاوُسٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏وَابْنِ عَبَّاسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏فَذَكَرَ مِثْلَهُ ‏","","",""],[2015,2015,"","","‏ ‏حَدَّثَنِي ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏مِقْسَمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏أَمَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الَّذِي ‏ ‏يَأْتِي ‏ ‏امْرَأَتَهُ وَهِيَ حَائِضٌ أَنْ يَتَصَدَّقَ بِدِينَارٍ أَوْ نِصْفِ دِينَارٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏مِقْسَمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ ‏ ‏وَرَوَاهُ ‏ ‏عَبْدُ الْكَرِيمِ أَبُو أُمَيَّةَ ‏ ‏مِثْلَهُ بِإِسْنَادِهِ ‏","","",""],[2016,2016,"","","‏ ‏حَدَّثَنِي ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَعَنَ ‏ ‏الْمُخَنَّثِينَ ‏ ‏مِنْ الرِّجَالِ ‏ ‏وَالْمُتَرَجِّلَاتِ ‏ ‏مِنْ النِّسَاءِ وَقَالَ أَخْرِجُوهُمْ مِنْ بُيُوتِكُمْ فَأَخْرَجَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فُلَانًا وَأَخْرَجَ ‏ ‏عُمَرُ ‏ ‏فُلَانًا ‏","","",""],[2017,2017,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏حَدَّثَنَا ‏ ‏بُكَيْرُ بْنُ الْأَخْنَسِ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ فَرَضَ الصَّلَاةَ عَلَى لِسَانِ نَبِيِّكُمْ عَلَى الْمُقِيمِ أَرْبَعًا وَعَلَى الْمُسَافِرِ رَكْعَتَيْنِ وَعَلَى الْخَائِفِ رَكْعَةً ‏","","",""],[2018,2018,"","","‏ ‏حَدَّثَنِي ‏ ‏يَزِيدُ يَعْنِي ابْنَ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏شَرِيكُ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنِ ‏ ‏التَّمِيمِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُمِرْتُ بِالسِّوَاكِ حَتَّى ظَنَنْتُ ‏ ‏أَوْ حَسِبْتُ ‏ ‏أَنْ سَيَنْزِلُ فِيهِ قُرْآنٌ ‏","","",""],[2019,2019,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏هَمَّامُ بْنُ يَحْيَى ‏ ‏حَدَّثَنَا ‏ ‏عَطَاءٌ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏دَخَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْكَعْبَةَ ‏ ‏وَفِيهَا سِتُّ ‏ ‏سَوَارٍ ‏ ‏فَقَامَ عِنْدَ كُلِّ ‏ ‏سَارِيَةٍ ‏ ‏وَلَمْ يُصَلِّ ‏","","",""],[2020,2020,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏يُوسُفَ بْنِ مِهْرَانَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏لَمَّا مَاتَ ‏ ‏عُثْمَانُ بْنُ مَظْعُونٍ ‏ ‏قَالَتْ امْرَأَةٌ هَنِيئًا لَكَ الْجَنَّةُ ‏ ‏عُثْمَانَ بْنَ مَظْعُونٍ ‏ ‏فَنَظَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَيْهَا نَظَرَ غَضْبَانَ فَقَالَ وَمَا ‏ ‏يُدْرِيكِ قَالَتْ يَا رَسُولَ اللَّهِ فَارِسُكَ وَصَاحِبُكَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَاللَّهِ ‏ ‏إِنِّي رَسُولُ اللَّهِ وَمَا أَدْرِي مَا يُفْعَلُ بِي فَأَشْفَقَ النَّاسُ عَلَى ‏ ‏عُثْمَانَ ‏ ‏فَلَمَّا مَاتَتْ ‏ ‏زَيْنَبُ ابْنَةُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْحَقِي بِسَلَفِنَا الصَّالِحِ الْخَيْرِ ‏ ‏عُثْمَانَ بْنِ مَظْعُونٍ ‏ ‏فَبَكَتْ النِّسَاءُ فَجَعَلَ ‏ ‏عُمَرُ ‏ ‏يَضْرِبُهُنَّ بِسَوْطِهِ فَأَخَذَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِيَدِهِ وَقَالَ مَهْلًا ‏ ‏يَا ‏ ‏عُمَرُ ‏ ‏ثُمَّ قَالَ ابْكِينَ وَإِيَّاكُنَّ وَنَعِيقَ الشَّيْطَانِ ثُمَّ قَالَ إِنَّهُ مَهْمَا كَانَ مِنْ الْعَيْنِ وَالْقَلْبِ فَمِنْ اللَّهِ عَزَّ وَجَلَّ وَمِنْ الرَّحْمَةِ وَمَا كَانَ مِنْ الْيَدِ وَاللِّسَانِ فَمِنْ الشَّيْطَانِ ‏","","",""],[2021,2021,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏طَاوُسٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏وَقَّتَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِأَهْلِ ‏ ‏الْمَدِينَةِ ‏ ‏ذَا الْحُلَيْفَةِ ‏ ‏وَلِأَهْلِ ‏ ‏الشَّامِ ‏ ‏الْجُحْفَةَ ‏ ‏وَلِأَهْلِ ‏ ‏الْيَمَنِ ‏ ‏يَلَمْلَمَ ‏ ‏وَلِأَهْلِ ‏ ‏نَجْدٍ ‏ ‏قَرْنًا ‏ ‏وَقَالَ هُنَّ وَقْتٌ لِأَهْلِهِنَّ وَلِمَنْ مَرَّ بِهِنَّ مِنْ غَيْرِ أَهْلِهِنَّ يُرِيدُ الْحَجَّ وَالْعُمْرَةَ فَمَنْ كَانَ مَنْزِلُهُ مِنْ وَرَاءِ الْمِيقَاتِ ‏ ‏فَإِهْلَالُهُ ‏ ‏مِنْ حَيْثُ يُنْشِئُ وَكَذَلِكَ حَتَّى أَهْلُ ‏ ‏مَكَّةَ ‏ ‏إِهْلَالُهُمْ ‏ ‏مِنْ حَيْثُ يُنْشِئُونَ ‏","","",""],[2022,2022,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏جَرِيرُ بْنُ حَازِمٍ ‏ ‏عَنْ ‏ ‏يَعْلَى بْنِ حَكِيمٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لِمَاعِزِ بْنِ مَالِكٍ ‏ ‏حِينَ أَتَاهُ فَأَقَرَّ عِنْدَهُ بِالزِّنَا ‏ ‏لَعَلَّكَ قَبَّلْتَ ‏ ‏أَوْ لَمَسْتَ ‏ ‏قَالَ لَا قَالَ فَنِكْتَهَا قَالَ نَعَمْ فَأَمَرَ بِهِ ‏ ‏فَرُجِمَ ‏","","",""],[2023,2023,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏حَدَّثَنَا ‏ ‏صَالِحُ بْنُ رُسْتُمَ أَبُو عَامِرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي مُلَيْكَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏أُقِيمَتْ صَلَاةُ الصُّبْحِ فَقَامَ رَجُلٌ ‏ ‏يُصَلِّي الرَّكْعَتَيْنِ فَجَذَبَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِثَوْبِهِ فَقَالَ ‏ ‏أَتُصَلِّي الصُّبْحَ أَرْبَعًا ‏","","",""],[2024,2024,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏عَبَّادُ بْنُ مَنْصُورٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏لَمَّا نَزَلَتْ ‏ { ‏وَالَّذِينَ يَرْمُونَ ‏ ‏الْمُحْصَنَاتِ ‏ ‏ثُمَّ لَمْ يَأْتُوا بِأَرْبَعَةِ شُهَدَاءَ فَاجْلِدُوهُمْ ثَمَانِينَ جَلْدَةً وَلَا تَقْبَلُوا لَهُمْ شَهَادَةً أَبَدًا ‏} ‏قَالَ ‏ ‏سَعْدُ بْنُ عُبَادَةَ ‏ ‏وَهُوَ سَيِّدُ ‏ ‏الْأَنْصَارِ ‏ ‏أَهَكَذَا نَزَلَتْ يَا رَسُولَ اللَّهِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏مَعْشَرَ ‏ ‏الْأَنْصَارِ ‏ ‏أَلَا تَسْمَعُونَ إِلَى مَا يَقُولُ سَيِّدُكُمْ قَالُوا يَا رَسُولَ اللَّهِ لَا تَلُمْهُ فَإِنَّهُ رَجُلٌ غَيُورٌ وَاللَّهِ مَا تَزَوَّجَ امْرَأَةً قَطُّ إِلَّا ‏ ‏بِكْرًا ‏ ‏وَمَا طَلَّقَ امْرَأَةً لَهُ قَطُّ فَاجْتَرَأَ رَجُلٌ مِنَّا عَلَى أَنْ يَتَزَوَّجَهَا مِنْ شِدَّةِ غَيْرَتِهِ فَقَالَ ‏ ‏سَعْدٌ ‏ ‏وَاللَّهِ يَا رَسُولَ اللَّهِ إِنِّي لَأَعْلَمُ أَنَّهَا حَقٌّ وَأَنَّهَا مِنْ اللَّهِ تَعَالَى وَلَكِنِّي قَدْ تَعَجَّبْتُ أَنِّي لَوْ وَجَدْتُ ‏ ‏لَكَاعًا ‏ ‏تَفَخَّذَهَا رَجُلٌ لَمْ يَكُنْ لِي أَنْ ‏ ‏أَهِيجَهُ ‏ ‏وَلَا أُحَرِّكَهُ حَتَّى آتِيَ بِأَرْبَعَةِ شُهَدَاءَ فَوَاللَّهِ لَا آتِي بِهِمْ حَتَّى يَقْضِيَ حَاجَتَهُ قَالَ فَمَا لَبِثُوا إِلَّا يَسِيرًا حَتَّى جَاءَ ‏ ‏هِلَالُ بْنُ أُمَيَّةَ ‏ ‏وَهُوَ أَحَدُ الثَّلَاثَةِ الَّذِينَ تِيبَ عَلَيْهِمْ فَجَاءَ مِنْ أَرْضِهِ عِشَاءً فَوَجَدَ عِنْدَ أَهْلِهِ رَجُلًا فَرَأَى بِعَيْنَيْهِ وَسَمِعَ بِأُذُنَيْهِ فَلَمْ ‏ ‏يَهِجْهُ ‏ ‏حَتَّى أَصْبَحَ ‏ ‏فَغَدَا ‏ ‏عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ إِنِّي جِئْتُ أَهْلِي عِشَاءً فَوَجَدْتُ عِنْدَهَا رَجُلًا فَرَأَيْتُ بِعَيْنَيَّ وَسَمِعْتُ بِأُذُنَيَّ فَكَرِهَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا جَاءَ بِهِ وَاشْتَدَّ عَلَيْهِ وَاجْتَمَعَتْ ‏ ‏الْأَنْصَارُ ‏ ‏فَقَالُوا قَدْ ابْتُلِينَا بِمَا قَالَ ‏ ‏سَعْدُ بْنُ عُبَادَةَ ‏ ‏الْآنَ يَضْرِبُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هِلَالَ بْنَ أُمَيَّةَ ‏ ‏وَيُبْطِلُ شَهَادَتَهُ فِي الْمُسْلِمِينَ فَقَالَ ‏ ‏هِلَالٌ ‏ ‏وَاللَّهِ إِنِّي لَأَرْجُو أَنْ يَجْعَلَ اللَّهُ لِي مِنْهَا مَخْرَجًا فَقَالَ ‏ ‏هِلَالٌ ‏ ‏يَا رَسُولَ اللَّهِ إِنِّي قَدْ أَرَى مَا اشْتَدَّ عَلَيْكَ مِمَّا جِئْتُ بِهِ وَاللَّهُ يَعْلَمُ إِنِّي لَصَادِقٌ وَ وَاللَّهِ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُرِيدُ أَنْ يَأْمُرَ بِضَرْبِهِ إِذْ أَنْزَلَ اللَّهُ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْوَحْيَ وَكَانَ إِذَا نَزَلَ عَلَيْهِ الْوَحْيُ عَرَفُوا ذَلِكَ فِي ‏ ‏تَرَبُّدِ ‏ ‏جِلْدِهِ ‏ ‏يَعْنِي فَأَمْسَكُوا عَنْهُ حَتَّى فَرَغَ مِنْ الْوَحْيِ ‏ ‏فَنَزَلَتْ ‏ { ‏وَالَّذِينَ يَرْمُونَ أَزْوَاجَهُمْ وَلَمْ يَكُنْ لَهُمْ شُهَدَاءُ إِلَّا أَنْفُسُهُمْ فَشَهَادَةُ أَحَدِهِمْ ‏} ‏الْآيَةَ ‏ ‏فَسُرِّيَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ أَبْشِرْ يَا ‏ ‏هِلَالُ ‏ ‏فَقَدْ جَعَلَ اللَّهُ لَكَ فَرَجًا وَمَخْرَجًا فَقَالَ ‏ ‏هِلَالٌ ‏ ‏قَدْ كُنْتُ أَرْجُو ذَاكَ مِنْ رَبِّي عَزَّ وَجَلَّ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَرْسِلُوا إِلَيْهَا فَأَرْسَلُوا إِلَيْهَا فَجَاءَتْ فَقَرَأَهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَيْهِمَا وَذَكَّرَهُمَا وَأَخْبَرَهُمَا أَنَّ عَذَابَ الْآخِرَةِ أَشَدُّ مِنْ عَذَابِ الدُّنْيَا فَقَالَ ‏ ‏هِلَالٌ ‏ ‏وَاللَّهِ يَا رَسُولَ اللَّهِ لَقَدْ صَدَقْتُ عَلَيْهَا فَقَالَتْ كَذَبَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَاعِنُوا ‏ ‏بَيْنَهُمَا فَقِيلَ ‏ ‏لِهِلَالٍ ‏ ‏اشْهَدْ فَشَهِدَ أَرْبَعَ شَهَادَاتٍ بِاللَّهِ إِنَّهُ لَمِنْ الصَّادِقِينَ فَلَمَّا كَانَ فِي الْخَامِسَةِ قِيلَ يَا ‏ ‏هِلَالُ ‏ ‏اتَّقِ اللَّهَ فَإِنَّ عَذَابَ الدُّنْيَا أَهْوَنُ مِنْ عَذَابِ الْآخِرَةِ وَإِنَّ هَذِهِ الْمُوجِبَةُ الَّتِي تُوجِبُ عَلَيْكَ الْعَذَابَ فَقَالَ وَاللَّهِ لَا يُعَذِّبُنِي اللَّهُ عَلَيْهَا كَمَا لَمْ يَجْلِدْنِي عَلَيْهَا فَشَهِدَ فِي الْخَامِسَةِ أَنَّ لَعْنَةَ ‏ ‏اللَّهِ عَلَيْهِ إِنْ كَانَ مِنْ الْكَاذِبِينَ ثُمَّ قِيلَ لَهَا اشْهَدِي أَرْبَعَ شَهَادَاتٍ بِاللَّهِ إِنَّهُ لَمِنْ الْكَاذِبِينَ فَلَمَّا كَانَتْ الْخَامِسَةُ قِيلَ لَهَا اتَّقِ اللَّهَ فَإِنَّ عَذَابَ الدُّنْيَا أَهْوَنُ مِنْ عَذَابِ الْآخِرَةِ وَإِنَّ هَذِهِ الْمُوجِبَةُ الَّتِي تُوجِبُ عَلَيْكِ الْعَذَابَ ‏ ‏فَتَلَكَّأَتْ ‏ ‏سَاعَةً ثُمَّ قَالَتْ وَاللَّهِ لَا أَفْضَحُ قَوْمِي فَشَهِدَتْ فِي الْخَامِسَةِ أَنَّ غَضَبَ اللَّهِ عَلَيْهَا إِنْ كَانَ مِنْ الصَّادِقِينَ فَفَرَّقَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْنَهُمَا وَقَضَى أَنَّهُ لَا ‏ ‏يُدْعَى ‏ ‏وَلَدُهَا لِأَبٍ وَلَا ‏ ‏تُرْمَى ‏ ‏هِيَ بِهِ وَلَا ‏ ‏يُرْمَى ‏ ‏وَلَدُهَا وَمَنْ ‏ ‏رَمَاهَا ‏ ‏أَوْ ‏ ‏رَمَى ‏ ‏وَلَدَهَا فَعَلَيْهِ ‏ ‏الْحَدُّ ‏ ‏وَقَضَى أَنْ لَا بَيْتَ لَهَا عَلَيْهِ وَلَا قُوتَ مِنْ أَجْلِ أَنَّهُمَا يَتَفَرَّقَانِ مِنْ غَيْرِ طَلَاقٍ وَلَا مُتَوَفًّى عَنْهَا وَقَالَ إِنْ جَاءَتْ بِهِ ‏ ‏أُصَيْهِبَ ‏ ‏أُرَيْسِحَ ‏ ‏حَمْشَ ‏ ‏السَّاقَيْنِ فَهُوَ ‏ ‏لِهِلَالٍ ‏ ‏وَإِنْ جَاءَتْ بِهِ ‏ ‏أَوْرَقَ ‏ ‏جَعْدًا ‏ ‏جُمَالِيًّا ‏ ‏خَدَلَّجَ ‏ ‏السَّاقَيْنِ ‏ ‏سَابِغَ ‏ ‏الْأَلْيَتَيْنِ ‏ ‏فَهُوَ لِلَّذِي رُمِيَتْ بِهِ فَجَاءَتْ بِهِ ‏ ‏أَوْرَقَ ‏ ‏جَعْدًا ‏ ‏جُمَالِيًّا ‏ ‏خَدَلَّجَ ‏ ‏السَّاقَيْنِ ‏ ‏سَابِغَ ‏ ‏الْأَلْيَتَيْنِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْلَا الْأَيْمَانُ لَكَانَ لِي وَلَهَا ‏ ‏شَانٌ ‏ ‏قَالَ ‏ ‏عِكْرِمَةُ ‏ ‏فَكَانَ بَعْدَ ذَلِكَ أَمِيرًا عَلَى ‏ ‏مِصْرٍ ‏ ‏وَكَانَ يُدْعَى لِأُمِّهِ وَمَا يُدْعَى لِأَبِيهِ ‏","","",""],[2025,2025,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏هِشَامٌ الدَّسْتُوَائِيُّ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَّامٍ ‏ ‏عَنِ ‏ ‏الْحَكَمِ بْنِ مِينَاءَ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏وَابْنِ عَبَّاسٍ ‏ ‏أَنَّهُمَا شَهِدَا عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ وَهُوَ عَلَى ‏ ‏أَعْوَادِ ‏ ‏الْمِنْبَرِ ‏ ‏لَيَنْتَهِيَنَّ أَقْوَامٌ عَنْ ‏ ‏وَدْعِهِمْ ‏ ‏الْجُمُعَاتِ أَوْ ‏ ‏لَيَخْتِمَنَّ ‏ ‏اللَّهُ عَزَّ وَجَلَّ عَلَى قُلُوبِهِمْ وَلَيُكْتَبَنَّ مِنْ الْغَافِلِينَ ‏","","",""],[2026,2026,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏فَرْقَدٍ السَّبَخِيِّ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ امْرَأَةً جَاءَتْ بِوَلَدِهَا إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ يَا رَسُولَ اللَّهِ إِنَّ بِهِ ‏ ‏لَمَمًا ‏ ‏وَإِنَّهُ يَأْخُذُهُ عِنْدَ طَعَامِنَا فَيُفْسِدُ عَلَيْنَا طَعَامَنَا قَالَ ‏ ‏فَمَسَحَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَدْرَهُ وَدَعَا لَهُ ‏ ‏فَتَعَّ ‏ ‏تَعَّةً ‏ ‏فَخَرَجَ مِنْ ‏ ‏فِيهِ مِثْلُ ‏ ‏الْجَرْوِ ‏ ‏الْأَسْوَدِ فَشُفِيَ ‏","","",""],[2027,2027,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏أَخْبَرَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ ‏ ‏عُقْبَةَ بْنَ عَامِرٍ ‏ ‏سَأَلَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ إِنَّ أُخْتَهُ ‏ ‏نَذَرَتْ ‏ ‏أَنْ تَمْشِيَ إِلَى ‏ ‏الْبَيْتِ ‏ ‏وَشَكَا إِلَيْهِ ضَعْفَهَا فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ غَنِيٌّ عَنْ ‏ ‏نَذْرِ ‏ ‏أُخْتِكَ فَلْتَرْكَبْ ‏ ‏وَلْتُهْدِ ‏ ‏بَدَنَةً ‏","","",""],[2028,2028,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاذُ بْنُ مُعَاذٍ ‏ ‏حَدَّثَنَا ‏ ‏حَاجِبُ بْنُ عُمَرَ ‏ ‏حَدَّثَنِي ‏ ‏عَمِّي ‏ ‏الْحَكَمُ بْنُ الْأَعْرَجِ ‏ ‏قَالَ ‏ ‏أَتَيْتُ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏وَهُوَ مُتَّكِئٌ عِنْدَ ‏ ‏زَمْزَمَ ‏ ‏فَجَلَسْتُ إِلَيْهِ وَكَانَ نِعْمَ الْجَلِيسُ فَقُلْتُ أَخْبِرْنِي عَنْ يَوْمِ ‏ ‏عَاشُورَاءَ ‏ ‏قَالَ عَنْ أَيِّ ‏ ‏بَالِهِ ‏ ‏تَسْأَلُ قُلْتُ عَنْ صَوْمِهِ قَالَ ‏ ‏إِذَا رَأَيْتَ هِلَالَ الْمُحَرَّمِ فَاعْدُدْ فَإِذَا أَصْبَحْتَ مِنْ تَاسِعَةٍ فَأَصْبِحْ مِنْهَا صَائِمًا قُلْتُ أَكَذَاكَ كَانَ يَصُومُهُ ‏ ‏مُحَمَّدٌ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ نَعَمْ ‏","","",""],[2029,2029,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏لَيْثًا ‏ ‏سَمِعْتُ ‏ ‏طَاوُسًا ‏ ‏يُحَدِّثُ عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏عَلِّمُوا وَيَسِّرُوا وَلَا تُعَسِّرُوا وَإِذَا غَضِبَ أَحَدُكُمْ فَلْيَسْكُتْ ‏","","",""],[2030,2030,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏يَزِيدَ أَبِي خَالِدٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْمِنْهَالَ بْنَ عَمْرٍو ‏ ‏يُحَدِّثُ عَنْ ‏ ‏سَعَيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَا مِنْ عَبْدٍ مُسْلِمٍ ‏ ‏يَعُودُ ‏ ‏مَرِيضًا لَمْ يَحْضُرْ أَجَلُهُ فَيَقُولُ سَبْعَ مَرَّاتٍ أَسْأَلُ اللَّهَ الْعَظِيمَ رَبَّ الْعَرْشِ الْعَظِيمِ أَنْ يَشْفِيَكَ إِلَّا عُوفِيَ ‏","","",""],[2031,2031,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏عَنِ ‏ ‏الْمِنْهَالِ بْنِ عَمْرٍو ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الْحَارِثِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏أُرَاهُ رَفَعَهُ ‏ ‏قَالَ ‏ ‏مَنْ ‏ ‏عَادَ ‏ ‏مَرِيضًا فَقَالَ أَسْأَلُ اللَّهَ الْعَظِيمَ رَبَّ الْعَرْشِ الْعَظِيمِ أَنْ يَشْفِيَكَ سَبْعَ مَرَّاتٍ شَفَاهُ اللَّهُ إِنْ كَانَ قَدْ ‏ ‏أُخِّرَ ‏ ‏يَعْنِي فِي أَجَلِهِ ‏ ‏و حَدَّثَنِي ‏ ‏يَزِيدُ ‏ ‏لَمْ يَشُكَّ فِي رَفْعِهِ وَوَافَقَهُ عَلَى الْإِسْنَادِ ‏","","",""],[2032,2032,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ ‏ ‏عُقْبَةَ بْنَ عَامِرٍ ‏ ‏أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ أَنَّ أُخْتَهُ ‏ ‏نَذَرَتْ ‏ ‏أَنْ تَمْشِيَ إِلَى ‏ ‏الْبَيْتِ ‏ ‏قَالَ ‏ ‏مُرْ أُخْتَكَ أَنْ تَرْكَبَ ‏ ‏وَلْتُهْدِ ‏ ‏بَدَنَةً ‏","","",""],[2033,2033,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي بِشْرٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سَعِيدَ بْنَ جُبَيْرٍ ‏ ‏يُحَدِّثُ عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ امْرَأَةً نَذَرَتْ أَنْ تَحُجَّ ‏ ‏فَمَاتَتْ فَأَتَى أَخُوهَا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَأَلَهُ عَنْ ذَلِكَ فَقَالَ أَرَأَيْتَ لَوْ كَانَ عَلَى أُخْتِكَ دَيْنٌ أَكُنْتَ قَاضِيَهُ قَالَ نَعَمْ قَالَ فَاقْضُوا اللَّهَ عَزَّ وَجَلَّ فَهُوَ أَحَقُّ بِالْوَفَاءِ ‏","","",""],[2034,2034,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَرَوْحٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏رَوْحٌ ‏ ‏سَمِعْتُ ‏ ‏مُسْلِمًا الْقُرِّيَّ ‏ ‏قَالَ ‏ ‏مُحَمَّدٌ ‏ ‏عَنْ ‏ ‏مُسْلِمٍ الْقُرِّيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏يَقُولُ ‏ ‏أَهَلَّ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالْعُمْرَةِ ‏ ‏وَأَهَلَّ ‏ ‏أَصْحَابُهُ بِالْحَجِّ ‏ ‏قَالَ ‏ ‏رَوْحٌ ‏ ‏أَهَلَّ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَصْحَابُهُ بِالْحَجِّ ‏ ‏فَمَنْ لَمْ يَكُنْ مَعَهُ ‏ ‏هَدْيٌ ‏ ‏أَحَلَّ ‏ ‏وَكَانَ مِمَّنْ لَمْ يَكُنْ مَعَهُ ‏ ‏هَدْيٌ ‏ ‏طَلْحَةُ ‏ ‏وَرَجُلٌ آخَرُ فَأَحَلَّا ‏","","",""],[2035,2035,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏سَمِعْتُ ‏ ‏يَحْيَى بْنَ الْمُجَبِّرِ التَّيْمِيَّ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَجُلًا أَتَاهُ فَقَالَ أَرَأَيْتَ رَجُلًا قَتَلَ رَجُلًا مُتَعَمِّدًا قَالَ ‏ { ‏جَزَاؤُهُ جَهَنَّمُ خَالِدًا فِيهَا وَغَضِبَ اللَّهُ عَلَيْهِ وَلَعَنَهُ وَأَعَدَّ لَهُ عَذَابًا عَظِيمًا ‏} ‏قَالَ لَقَدْ أُنْزِلَتْ فِي آخِرِ مَا نَزَلَ مَا ‏ ‏نَسَخَهَا ‏ ‏شَيْءٌ حَتَّى ‏ ‏قُبِضَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَمَا نَزَلَ وَحْيٌ بَعْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ أَرَأَيْتَ إِنْ تَابَ وَآمَنَ وَعَمِلَ صَالِحًا ثُمَّ اهْتَدَى قَالَ وَأَنَّى لَهُ بِالتَّوْبَةِ وَقَدْ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏ثَكِلَتْهُ ‏ ‏أُمُّهُ رَجُلٌ قَتَلَ رَجُلًا مُتَعَمِّدًا يَجِيءُ يَوْمَ الْقِيَامَةِ آخِذًا قَاتِلَهُ بِيَمِينِهِ ‏ ‏أَوْ بِيَسَارِهِ ‏ ‏وَآخِذًا رَأْسَهُ بِيَمِينِهِ ‏ ‏أَوْ شِمَالِهِ ‏ ‏تَشْخَبُ ‏ ‏أَوْدَاجُهُ ‏ ‏دَمًا فِي قُبُلِ الْعَرْشِ يَقُولُ يَا رَبِّ سَلْ عَبْدَكَ فِيمَ قَتَلَنِي ‏","","",""],[2036,2036,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏يَحْيَى أَبِي عُمَرَ ‏ ‏قَالَ ‏ ‏ذَكَرُوا ‏ ‏النَّبِيذَ ‏ ‏عِنْدَ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏فَقَالَ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُنْبَذُ ‏ ‏لَهُ فِي ‏ ‏السِّقَاءِ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏مِثْلَ لَيْلَةِ ‏ ‏الِاثْنَيْنِ فَيَشْرَبُهُ يَوْمَ ‏ ‏الِاثْنَيْنِ وَالثُّلَاثَاءِ إِلَى الْعَصْرِ فَإِنْ ‏ ‏فَضَلَ ‏ ‏مِنْهُ شَيْءٌ سَقَاهُ الْخُدَّامَ أَوْ صَبَّهُ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏وَلَا أَحْسِبُهُ إِلَّا قَالَ وَيَوْمَ الْأَرْبِعَاءِ إِلَى الْعَصْرِ فَإِنْ ‏ ‏فَضَلَ ‏ ‏مِنْهُ شَيْءٌ سَقَاهُ الْخُدَّامَ أَوْ صَبَّهُ ‏","","",""],[2037,2037,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَدِيِّ بْنِ ثَابِتٍ ‏ ‏وَعَطَاءُ بْنُ السَّائِبِ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏رَفَعَهُ أَحَدُهُمَا إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ ‏ ‏جِبْرِيلَ ‏ ‏كَانَ ‏ ‏يَدُسُّ ‏ ‏فِي فَمِ ‏ ‏فِرْعَوْنَ ‏ ‏الطِّينَ مَخَافَةَ أَنْ يَقُولَ لَا إِلَهَ إِلَّا اللَّهُ ‏","","",""],[2038,2038,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ فِي ‏ ‏السَّلَفِ ‏ ‏فِي ‏ ‏حَبَلِ الْحَبَلَةِ ‏ ‏رِبًا ‏","","",""],[2039,2039,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏حَبِيبٍ يَعْنِي ابْنَ الشَّهِيدِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي مُلَيْكَةَ ‏ ‏قَالَ ‏ ‏شَهِدْتُ ‏ ‏ابْنَ الزُّبَيْرِ ‏ ‏وَابْنَ عَبَّاسٍ ‏ ‏فَقَالَ ‏ ‏ابْنُ الزُّبَيْرِ ‏ ‏لِابْنِ عَبَّاسٍ ‏ ‏أَتَذْكُرُ حِينَ اسْتَقْبَلْنَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَدْ جَاءَ مِنْ سَفَرٍ فَقَالَ نَعَمْ ‏ ‏فَحَمَلَنِي وَفُلَانًا ‏ ‏غُلَامًا مِنْ ‏ ‏بَنِي هَاشِمٍ ‏ ‏وَتَرَكَكَ ‏","","",""],[2040,2040,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سِمَاكِ بْنِ حَرْبٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَدْخُلُ عَلَيْكُمْ رَجُلٌ يَنْظُرُ بِعَيْنِ شَيْطَانٍ ‏ ‏أَوْ بِعَيْنَيْ شَيْطَانٍ ‏ ‏قَالَ فَدَخَلَ رَجُلٌ أَزْرَقُ فَقَالَ يَا ‏ ‏مُحَمَّدُ ‏ ‏عَلَامَ سَبَبْتَنِي ‏ ‏أَوْ شَتَمْتَنِي أَوْ نَحْوَ هَذَا ‏ ‏قَالَ وَجَعَلَ يَحْلِفُ قَالَ فَنَزَلَتْ هَذِهِ الْآيَةُ فِي الْمُجَادَلَةِ ‏ { ‏وَيَحْلِفُونَ عَلَى الْكَذِبِ وَهُمْ يَعْلَمُونَ ‏} ‏وَالْآيَةُ الْأُخْرَى ‏","","",""],[2041,2041,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سِمَاكِ بْنِ حَرْبٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ فِي ‏ ‏الدَّجَّالِ ‏ ‏أَعْوَرُ ‏ ‏هِجَانٌ ‏ ‏أَزْهَرُ ‏ ‏كَأَنَّ رَأْسَهُ ‏ ‏أَصَلَةٌ ‏ ‏أَشْبَهُ النَّاسِ ‏ ‏بِعَبْدِ الْعُزَّى بْنِ قَطَنٍ ‏ ‏فَإِمَّا هَلَكَ الْهُلَّكُ فَإِنَّ رَبَّكُمْ تَعَالَى لَيْسَ بِأَعْوَرَ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏فَحَدَّثْتُ ‏ ‏بِهِ ‏ ‏قَتَادَةَ ‏ ‏فَحَدَّثَنِي ‏ ‏بِنَحْوٍ مِنْ هَذَا ‏","","",""],[2042,2042,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاذُ بْنُ هِشَامٍ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبَّاسٍ ‏ ‏أَنَّ رَجُلًا أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا نَبِيَّ اللَّهِ إِنِّي شَيْخٌ كَبِيرٌ عَلِيلٌ يَشُقُّ عَلَيَّ ‏ ‏الْقِيَامُ ‏ ‏فَأْمُرْنِي بِلَيْلَةٍ لَعَلَّ اللَّهَ يُوَفِّقُنِي فِيهَا ‏ ‏لِلَيْلَةِ ‏ ‏الْقَدْرِ قَالَ عَلَيْكَ بِالسَّابِعَةِ ‏","","",""],[2043,2043,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي حَمْزَةَ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏يَقُولُ ‏ ‏مَرَّ بِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنَا أَلْعَبُ مَعَ ‏ ‏الْغِلْمَانِ فَاخْتَبَأْتُ مِنْهُ خَلْفَ بَابٍ ‏ ‏فَدَعَانِي ‏ ‏فَحَطَأَنِي ‏ ‏حَطْأَةً ‏ ‏ثُمَّ بَعَثَ بِي إِلَى ‏ ‏مُعَاوِيَةَ ‏","","",""],[2044,2044,"","","‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي بِشْرٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَصُومُ حَتَّى نَقُولَ لَا يُرِيدُ أَنْ يُفْطِرَ وَيُفْطِرُ حَتَّى نَقُولَ لَا يُرِيدُ أَنْ يَصُومَ وَمَا صَامَ شَهْرًا مُتَتَابِعًا غَيْرَ رَمَضَانَ مُنْذُ قَدِمَ ‏ ‏الْمَدِينَةَ ‏","","",""],[2045,2045,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ أَبِي زِيَادٍ ‏ ‏عَنِ ‏ ‏مُجَاهِدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏أَهَلَّ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالْحَجِّ فَلَمَّا قَدِمَ طَافَ ‏ ‏بِالْبَيْتِ ‏ ‏وَبَيْنَ ‏ ‏الصَّفَا ‏ ‏وَالْمَرْوَةِ ‏ ‏وَلَمْ يُقَصِّرْ وَلَمْ يُحِلَّ مِنْ أَجْلِ ‏ ‏الْهَدْيِ ‏ ‏وَأَمَرَ مَنْ لَمْ يَكُنْ سَاقَ ‏ ‏الْهَدْيَ ‏ ‏أَنْ يَطُوفَ وَأَنْ ‏ ‏يَسْعَى وَيُقَصِّرَ ‏ ‏أَوْ يَحْلِقَ ‏ ‏ثُمَّ يُحِلَّ ‏","","",""],[2046,2046,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏جَابِرٌ الْجُعْفِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو جَعْفَرٍ مُحَمَّدُ بْنُ عَلِيٍّ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَرَّ بِقِدْرٍ فَأَخَذَ مِنْهَا ‏ ‏عَرْقًا ‏ ‏وَكَتِفًا فَأَكَلَهُ ثُمَّ صَلَّى وَلَمْ يَتَوَضَّأْ ‏","","",""],[2047,2047,"","","‏ ‏قَالَ ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏دَاوُدَ بْنِ عَلِيٍّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صُومُوا ‏ ‏يَوْمَ عَاشُورَاءَ ‏ ‏وَخَالِفُوا فِيهِ ‏ ‏الْيَهُودَ ‏ ‏صُومُوا قَبْلَهُ يَوْمًا أَوْ بَعْدَهُ يَوْمًا ‏","","",""],[2048,2048,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِذَا ‏ ‏احْتَجَمَ ‏ ‏احْتَجَمَ ‏ ‏فِي ‏ ‏الْأَخْدَعَيْنِ ‏ ‏قَالَ فَدَعَا غُلَامًا ‏ ‏لِبَنِي بَيَاضَةَ ‏ ‏فَحَجَمَهُ ‏ ‏وَأَعْطَى ‏ ‏الْحَجَّامَ ‏ ‏أَجْرَهُ ‏ ‏مُدًّا ‏ ‏وَنِصْفًا قَالَ وَكَلَّمَ ‏ ‏مَوَالِيَهُ ‏ ‏فَحَطُّوا عَنْهُ نِصْفَ ‏ ‏مُدٍّ ‏ ‏وَكَانَ عَلَيْهِ ‏ ‏مُدَّانِ ‏","","",""],[2049,2049,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الشَّعْبِيَّ ‏ ‏يُحَدِّثُ عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏وَابْنِ عَبَّاسٍ ‏ ‏قَالَا ‏ ‏سَنَّ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الصَّلَاةَ فِي السَّفَرِ رَكْعَتَيْنِ وَهِيَ تَمَامٌ ‏ ‏وَالْوَتْرُ ‏ ‏فِي السَّفَرِ سُنَّةٌ ‏","","",""],[2050,2050,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ ‏ ‏عَمَّارٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَنْ بَنَى لِلَّهِ مَسْجِدًا وَلَوْ ‏ ‏كَمَفْحَصِ ‏ ‏قَطَاةٍ ‏ ‏لِبَيْضِهَا بَنَى اللَّهُ لَهُ بَيْتًا فِي الْجَنَّةِ ‏","","",""],[2051,2051,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا جَمْرَةَ الضُّبَعِيَّ ‏ ‏قَالَ ‏ ‏تَمَتَّعْتُ ‏ ‏فَنَهَانِي نَاسٌ عَنْ ذَلِكَ فَأَتَيْتُ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏فَسَأَلْتُهُ عَنْ ذَلِكَ فَأَمَرَنِي بِهَا قَالَ ثُمَّ انْطَلَقْتُ إِلَى الْبَيْتِ فَنِمْتُ فَأَتَانِي آتٍ فِي مَنَامِي فَقَالَ ‏ ‏عُمْرَةٌ مُتَقَبَّلَةٌ وَحَجٌّ ‏ ‏مَبْرُورٌ ‏ ‏قَالَ فَأَتَيْتُ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏فَأَخْبَرْتُهُ بِالَّذِي رَأَيْتُ فَقَالَ اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ سُنَّةُ ‏ ‏أَبِي الْقَاسِمِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَالَ فِي ‏ ‏الْهَدْيِ ‏ ‏جَزُورٌ ‏ ‏أَوْ بَقَرَةٌ أَوْ شَاةٌ أَوْ شِرْكٌ فِي دَمٍ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏مَا أَسْنَدَ ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي جَمْرَةَ ‏ ‏إِلَّا وَاحِدًا ‏ ‏وَأَبُو جَمْرَةَ ‏ ‏أَوْثَقُ مِنْ ‏ ‏أَبِي حَمْزَةَ ‏","","",""],[2052,2052,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي السَّفَرِ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ شُفَيٍّ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏جَعَلَ النَّاسُ يَسْأَلُونَهُ عَنْ الصَّلَاةِ فِي السَّفَرِ فَقَالَ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا خَرَجَ مِنْ أَهْلِهِ لَمْ يُصَلِّ إِلَّا رَكْعَتَيْنِ حَتَّى يَرْجِعَ إِلَى أَهْلِهِ ‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ شُفَيٍّ ‏ ‏قَالَ ‏ ‏كُنْتُ عِنْدَ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏","","",""],[2053,2053,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏الْمُجَثَّمَةِ ‏ ‏وَالْجَلَّالَةِ ‏ ‏وَأَنْ يُشْرَبَ مِنْ ‏ ‏فِي ‏ ‏السِّقَاءِ ‏","","",""],[2054,2054,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنِ ‏ ‏النَّضْرِ بْنِ أَنَسٍ ‏ ‏قَالَ ‏ ‏كُنْتُ عِنْدَ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏وَهُوَ يُفْتِي النَّاسَ لَا يُسْنِدُ إِلَى نَبِيِّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شَيْئًا مِنْ فُتْيَاهُ حَتَّى جَاءَهُ رَجُلٌ مِنْ أَهْلِ ‏ ‏الْعِرَاقِ ‏ ‏فَقَالَ إِنِّي رَجُلٌ مِنْ أَهْلِ ‏ ‏الْعِرَاقِ ‏ ‏وَإِنِّي أُصَوِّرُ هَذِهِ ‏ ‏التَّصَاوِيرَ ‏ ‏فَقَالَ لَهُ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏ادْنُهْ ‏ ‏إِمَّا مَرَّتَيْنِ أَوْ ثَلَاثًا ‏ ‏فَدَنَا فَقَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ صَوَّرَ صُورَةً فِي الدُّنْيَا يُكَلَّفُ يَوْمَ الْقِيَامَةِ أَنْ يَنْفُخَ فِيهِ الرُّوحَ وَلَيْسَ بِنَافِخٍ ‏","","",""],[2055,2055,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الْفَضْلِ ‏ ‏عَنْ ‏ ‏نَافِعِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْأَيِّمُ ‏ ‏أَحَقُّ بِنَفْسِهَا مِنْ ‏ ‏وَلِيِّهَا ‏ ‏وَالْبِكْرُ ‏ ‏تُسْتَأْذَنُ فِي نَفْسِهَا وَإِذْنُهَا صُمَاتُهَا ‏","","",""],[2056,2056,"","","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏مَخْرَمَةَ بْنِ سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏كُرَيْبٍ ‏ ‏مَوْلَى ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عَبَّاسٍ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّهُ بَاتَ عِنْدَ ‏ ‏مَيْمُونَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهِيَ خَالَتُهُ قَالَ فَاضْطَجَعْتُ فِي عَرْضِ الْوِسَادَةِ وَاضْطَجَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَهْلُهُ فِي طُولِهَا فَنَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى إِذَا انْتَصَفَ اللَّيْلُ ‏ ‏أَوْ قَبْلَهُ بِقَلِيلٍ أَوْ بَعْدَهُ بِقَلِيلٍ ‏ ‏اسْتَيْقَظَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَجَلَسَ يَمْسَحُ النَّوْمَ عَنْ وَجْهِهِ بِيَدِهِ ثُمَّ ‏ ‏قَرَأَ الْعَشْرَ الْآيَاتِ خَوَاتِيمَ سُورَةِ ‏ ‏آلِ ‏ ‏عِمْرَانَ ‏ ‏ثُمَّ قَامَ إِلَى ‏ ‏شَنٍّ ‏ ‏مُعَلَّقَةٍ فَتَوَضَّأَ مِنْهَا فَأَحْسَنَ وُضُوءَهُ ثُمَّ قَامَ ‏ ‏يُصَلِّي قَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏فَقُمْتُ فَصَنَعْتُ مِثْلَ الَّذِي صَنَعَ ثُمَّ ذَهَبْتُ فَقُمْتُ إِلَى جَنْبِهِ فَوَضَعَ يَدَهُ عَلَى رَأْسِي وَأَخَذَ أُذُنِي الْيُمْنَى فَفَتَلَهَا فَصَلَّى رَكْعَتَيْنِ ثُمَّ رَكْعَتَيْنِ ثُمَّ رَكْعَتَيْنِ ثُمَّ رَكْعَتَيْنِ ثُمَّ رَكْعَتَيْنِ ثُمَّ رَكْعَتَيْنِ ثُمَّ ‏ ‏أَوْتَرَ ‏ ‏ثُمَّ اضْطَجَعَ حَتَّى أَتَاهُ الْمُؤَذِّنُ فَقَامَ فَصَلَّى رَكْعَتَيْنِ خَفِيفَتَيْنِ ثُمَّ خَرَجَ فَصَلَّى الصُّبْحَ ‏","","",""],[2057,2057,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَمَّارِ بْنِ أَبِي عَمَّارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏رَأَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الْمَنَامِ بِنِصْفِ النَّهَارِ ‏ ‏أَشْعَثَ ‏ ‏أَغْبَرَ ‏ ‏مَعَهُ ‏ ‏قَارُورَةٌ ‏ ‏فِيهَا دَمٌ يَلْتَقِطُهُ ‏ ‏أَوْ يَتَتَبَّعُ فِيهَا شَيْئًا ‏ ‏قَالَ قُلْتُ يَا رَسُولَ اللَّهِ مَا هَذَا قَالَ دَمُ ‏ ‏الْحُسَيْنِ ‏ ‏وَأَصْحَابِهِ لَمْ أَزَلْ أَتَتَبَّعُهُ مُنْذُ الْيَوْمَ ‏ ‏قَالَ ‏ ‏عَمَّارٌ ‏ ‏فَحَفِظْنَا ذَلِكَ الْيَوْمَ فَوَجَدْنَاهُ قُتِلَ ذَلِكَ الْيَوْمَ ‏","","",""],[2058,2058,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ كُهَيْلٍ ‏ ‏عَنْ ‏ ‏عِمْرَانَ أَبِي الْحَكَمِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَتْ ‏ ‏قُرَيْشٌ ‏ ‏لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ادْعُ لَنَا رَبَّكَ أَنْ يَجْعَلَ لَنَا ‏ ‏الصَّفَا ‏ ‏ذَهَبًا وَنُؤْمِنُ بِكَ قَالَ وَتَفْعَلُونَ قَالُوا نَعَمْ قَالَ فَدَعَا فَأَتَاهُ ‏ ‏جِبْرِيلُ ‏ ‏فَقَالَ إِنَّ رَبَّكَ عَزَّ وَجَلَّ يَقْرَأُ عَلَيْكَ السَّلَامَ وَيَقُولُ ‏ ‏إِنْ شِئْتَ أَصْبَحَ لَهُمْ ‏ ‏الصَّفَا ‏ ‏ذَهَبًا فَمَنْ كَفَرَ بَعْدَ ذَلِكَ مِنْهُمْ عَذَّبْتُهُ عَذَابًا لَا أُعَذِّبُهُ أَحَدًا مِنْ الْعَالَمِينَ وَإِنْ شِئْتَ فَتَحْتُ لَهُمْ بَابَ التَّوْبَةِ وَالرَّحْمَةِ قَالَ بَلْ بَابُ التَّوْبَةِ وَالرَّحْمَةِ ‏","","",""],[2059,2059,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا الْعَالِيَةِ ‏ ‏يَقُولُ حَدَّثَنِي ‏ ‏ابْنُ عَمِّ نَبِيِّكُمْ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَعْنِي ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَنْبَغِي لِأَحَدٍ أَنْ يَقُولَ أَنَا خَيْرٌ مِنْ ‏ ‏يُونُسَ بْنِ مَتَّى ‏ ‏وَنَسَبَهُ إِلَى أَبِيهِ ‏","","",""],[2060,2060,"","","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ الْمَكِّيِّ ‏ ‏عَنْ ‏ ‏طَاوُسٍ الْيَمَانِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يُعَلِّمُهُمْ الدُّعَاءَ كَمَا يُعَلِّمُهُمْ السُّورَةَ مِنْ الْقُرْآنِ يَقُولُ قُولُوا ‏ ‏اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عَذَابِ جَهَنَّمَ وَأَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ وَأَعُوذُ بِكَ مِنْ فِتْنَةِ ‏ ‏الْمَسِيحِ الدَّجَّالِ ‏ ‏وَأَعُوذُ بِكَ مِنْ فِتْنَةِ الْمَحْيَا وَالْمَمَاتِ ‏","","",""],[2061,2061,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يَزِيدَ ‏ ‏عَنْ ‏ ‏دَاوُدَ يَعْنِي ابْنَ أَبِي الْفُرَاتِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏صَلَّى نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالنَّاسِ يَوْمَ فِطْرٍ رَكْعَتَيْنِ بِغَيْرِ أَذَانٍ وَلَا إِقَامَةٍ ثُمَّ خَطَبَ بَعْدَ الصَّلَاةِ ثُمَّ أَخَذَ بِيَدِ ‏ ‏بِلَالٍ ‏ ‏فَانْطَلَقَ إِلَى النِّسَاءِ فَخَطَبَهُنَّ ثُمَّ أَمَرَ ‏ ‏بِلَالًا ‏ ‏بَعْدَمَا ‏ ‏قَفَّى ‏ ‏مِنْ عِنْدِهِنَّ ‏ ‏أَنْ يَأْتِيَهُنَّ فَيَأْمُرَهُنَّ أَنْ يَتَصَدَّقْنَ ‏","","",""],[2062,2062,"","","‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏أَحْمَدُ بْنُ مُحَمَّدِ بْنِ حَنْبَلٍ ‏ ‏مِنْ كِتَابِهِ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ الْأُمَوِيُّ ‏ ‏قَالَ ‏ ‏الْأَعْمَشُ ‏ ‏حَدَّثَنَا عَنْ ‏ ‏طَارِقٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏قَالَ قَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اللَّهُمَّ إِنَّكَ أَذَقْتَ أَوَائِلَ ‏ ‏قُرَيْشٍ ‏ ‏نَكَالًا ‏ ‏فَأَذِقْ آخِرَهُمْ ‏ ‏نَوَالًا ‏","","",""],[2063,2063,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ رَبِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏عَنِ ‏ ‏الْحَسَنِ بْنِ مُسْلِمٍ ‏ ‏عَنْ ‏ ‏طَاوُسٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏شَهِدْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْعِيدَ ‏ ‏وَأَبِي بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏وَعُثْمَانَ ‏ ‏فَكُلُّهُمْ ‏ ‏صَلَّى قَبْلَ الْخُطْبَةِ بِغَيْرِ أَذَانٍ وَلَا إِقَامَةٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ رَبِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمِثْلِ ذَلِكَ ‏","","",""],[2064,2064,"","","‏ ‏حَدَّثَنَا ‏ ‏مُؤَمَّلٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏عَنِ ‏ ‏الْحَسَنِ بْنِ مُسْلِمٍ ‏ ‏عَنْ ‏ ‏طَاوُسٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏صَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْعِيدَ ثُمَّ خَطَبَ وَصَلَّى ‏ ‏أَبُو بَكْرٍ ‏ ‏ثُمَّ خَطَبَ ‏ ‏وَعُمَرُ ‏ ‏ثُمَّ خَطَبَ ‏ ‏وَعُثْمَانُ ‏ ‏ثُمَّ خَطَبَ بِغَيْرِ أَذَانٍ وَلَا إِقَامَةٍ ‏","","",""],[2065,2065,"","","‏ ‏حَدَّثَنَا ‏ ‏الْقَاسِمُ بْنُ مَالِكٍ أَبُو جَعْفَرٍ ‏ ‏عَنْ ‏ ‏حَنْظَلَةَ السَّدُوسِيِّ ‏ ‏عَنْ ‏ ‏شَهْرِ بْنِ حَوْشَبٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏صَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْعِيدَ رَكْعَتَيْنِ لَا يَقْرَأُ فِيهِمَا إِلَّا ‏ ‏بِأُمِّ الْكِتَابِ ‏ ‏لَمْ يَزِدْ عَلَيْهَا شَيْئًا ‏","","",""],[2066,2066,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ أَبِي حَكِيمٍ ‏ ‏حَدَّثَنَا ‏ ‏الْحَكَمُ يَعْنِي ابْنَ أَبَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عِكْرِمَةَ ‏ ‏يَقُولُ قَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏رُكِزَتْ ‏ ‏الْعَنَزَةُ ‏ ‏بَيْنَ يَدَيْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِعَرَفَاتٍ ‏ ‏فَصَلَّى إِلَيْهَا وَالْحِمَارُ يَمُرُّ مِنْ وَرَاءِ ‏ ‏الْعَنَزَةِ ‏","","",""],[2067,2067,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْقُدُّوسِ بْنُ بَكْرِ بْنِ خُنَيْسٍ ‏ ‏حَدَّثَنَا ‏ ‏الْحَجَّاجُ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏مِقْسَمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏حَاصَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَهْلَ ‏ ‏الطَّائِفِ ‏ ‏فَخَرَجَ إِلَيْهِ عَبْدَانِ فَأَعْتَقَهُمَا أَحَدُهُمَا ‏ ‏أَبُو بَكْرَةَ ‏ ‏وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُعْتِقُ الْعَبِيدَ إِذَا خَرَجُوا إِلَيْهِ ‏","","",""],[2068,2068,"","","‏ ‏حَدَّثَنَا ‏ ‏الْقَاسِمُ بْنُ مَالِكٍ الْمُزَنِيُّ أَبُو جَعْفَرٍ ‏ ‏عَنْ ‏ ‏أَيُّوبَ بْنِ عَائِذٍ ‏ ‏عَنْ ‏ ‏بُكَيْرِ بْنِ الْأَخْنَسِ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ فَرَضَ الصَّلَاةَ عَلَى لِسَانِ نَبِيِّكُمْ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الْحَضَرِ أَرْبَعًا وَفِي السَّفَرِ رَكْعَتَيْنِ وَفِي الْخَوْفِ رَكْعَةً ‏","","",""],[2069,2069,"","","‏ ‏حَدَّثَنَا ‏ ‏عَمَّارُ بْنُ مُحَمَّدٍ ‏ ‏ابْنُ أُخْتِ ‏ ‏سُفْيَانَ الثَّوْرِيِّ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏كُرَيْبٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيَعْجِزُ أَحَدُكُمْ إِذَا ‏ ‏أَتَى ‏ ‏أَهْلَهُ أَنْ يَقُولَ بِسْمِ اللَّهِ اللَّهُمَّ جَنِّبْنِي الشَّيْطَانَ وَجَنِّبْ الشَّيْطَانَ مَا رَزَقْتَنِي فَإِنْ اللَّهُ قَضَى بَيْنَهُمَا فِي ذَلِكَ وَلَدًا لَمْ يَضُرَّهُ الشَّيْطَانُ أَبَدًا ‏","","",""],[2070,2070,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَاصِمٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏قَالَ ‏ ‏قَالَ لِي ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏يَا ‏ ‏سَعِيدُ ‏ ‏أَلَكَ امْرَأَةٌ قَالَ قُلْتُ لَا قَالَ فَإِذَا رَجَعْتَ فَتَزَوَّجْ قَالَ فَعُدْتُ إِلَيْهِ فَقَالَ يَا ‏ ‏سَعِيدُ ‏ ‏أَتَزَوَّجْتَ قَالَ قُلْتُ لَا قَالَ ‏ ‏تَزَوَّجْ فَإِنَّ خَيْرَ هَذِهِ الْأُمَّةِ أَكْثَرُهُمْ نِسَاءً ‏","","",""],[2071,2071,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَاصِمٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَلِيٍّ الرَّحَبِيُّ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏اغْتَسَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ جَنَابَةٍ فَلَمَّا خَرَجَ رَأَى لُمْعَةً عَلَى ‏ ‏مَنْكِبِهِ ‏ ‏الْأَيْسَرِ لَمْ يُصِبْهَا الْمَاءُ فَأَخَذَ مِنْ شَعَرِهِ فَبَلَّهَا ثُمَّ مَضَى إِلَى الصَّلَاةِ ‏","","",""],[2072,2072,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏ثَعْلَبَةَ بْنِ مُسْلِمٍ الْخَثْعَمِيِّ ‏ ‏عَنْ ‏ ‏أَبِي كَعْبٍ ‏ ‏مَوْلَى ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قِيلَ لَهُ يَا رَسُولَ اللَّهِ لَقَدْ أَبْطَأَ عَنْكَ ‏ ‏جِبْرِيلُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏فَقَالَ ‏ ‏وَلِمَ لَا يُبْطِئُ عَنِّي وَأَنْتُمْ حَوْلِي لَا ‏ ‏تَسْتَنُّونَ ‏ ‏وَلَا تُقَلِّمُونَ أَظْفَارَكُمْ وَلَا تَقُصُّونَ شَوَارِبَكُمْ وَلَا تُنَقُّونَ ‏ ‏رَوَاجِبَكُمْ ‏","","",""],[2073,2073,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي خَالِدٍ يَزِيدَ ‏ ‏عَنِ ‏ ‏الْمِنْهَالِ بْنِ عَمْرٍو ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ أَتَى مَرِيضًا لَمْ يَحْضُرْ أَجَلُهُ فَقَالَ سَبْعَ مَرَّاتٍ أَسْأَلُ اللَّهَ الْعَظِيمَ رَبَّ الْعَرْشِ الْكَرِيمِ أَنْ يَشْفِيَهُ إِلَّا عُوفِيَ ‏","","",""],[2074,2074,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏مَرَّ بِي النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَرِيبًا مِنْ ‏ ‏زَمْزَمَ ‏ ‏فَدَعَا بِمَاءٍ وَاسْتَسْقَى فَأَتَيْتُهُ بِدَلْوٍ مِنْ ‏ ‏زَمْزَمَ ‏ ‏فَشَرِبَ وَهُوَ قَائِمٌ ‏","","",""],[2075,2075,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ الْهَاشِمِيُّ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ سَعْدٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏صَالِحُ بْنُ كَيْسَانَ ‏ ‏وَابْنُ أَخِي ابْنِ شِهَابٍ ‏ ‏كِلَاهُمَا ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏وَيَعْقُوبُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏صَالِحٍ ‏ ‏قَالَ ‏ ‏ابْنُ شِهَابٍ ‏ ‏أَخْبَرَنِي ‏ ‏عُبَيْدُ اللَّهِ بْنُ عَبْدِ اللَّهِ ‏ ‏أَنَّ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏أَخْبَرَهُ قَالَ ‏ ‏بَعَثَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَبْدَ اللَّهِ بْنَ حُذَافَةَ ‏ ‏بِكِتَابِهِ إِلَى ‏ ‏كِسْرَى ‏ ‏قَالَ فَدَفَعَهُ إِلَى عَظِيمِ ‏ ‏الْبَحْرَيْنِ ‏ ‏يَدْفَعُهُ عَظِيمُ ‏ ‏الْبَحْرَيْنِ ‏ ‏إِلَى ‏ ‏كِسْرَى ‏ ‏قَالَ ‏ ‏يَعْقُوبُ ‏ ‏فَدَفَعَهُ عَظِيمُ ‏ ‏الْبَحْرَيْنِ ‏ ‏إِلَى ‏ ‏كِسْرَى ‏ ‏فَلَمَّا قَرَأَهُ مَزَّقَهُ ‏ ‏قَالَ ‏ ‏ابْنُ شِهَابٍ ‏ ‏فَحَسِبْتُ ‏ ‏ابْنَ الْمُسَيَّبِ ‏ ‏قَالَ ‏ ‏فَدَعَا عَلَيْهِمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِأَنْ يُمَزَّقُوا كُلَّ مُمَزَّقٍ ‏","","",""],[2076,2076,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏مِقْسَمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏صَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ فَتْحِ ‏ ‏مَكَّةَ ‏ ‏حَتَّى أَتَى ‏ ‏قُدَيْدًا ‏ ‏فَأُتِيَ ‏ ‏بِقَدَحٍ ‏ ‏مِنْ لَبَنٍ فَأَفْطَرَ ‏ ‏وَأَمَرَ النَّاسَ أَنْ يُفْطِرُوا ‏","","",""],[2077,2077,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏مِقْسَمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏احْتَجَمَ ‏ ‏بِالْقَاحَةِ ‏ ‏وَهُوَ صَائِمٌ ‏","","",""],[2078,2078,"","","‏ ‏حَدَّثَنَا ‏ ‏حُجَيْنُ بْنُ الْمُثَنَّى ‏ ‏وَيُونُسُ يَعْنِي ابْنَ مُحَمَّدٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ يَعْنِي ابْنَ أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ عُقْبَةَ ‏ ‏عَنْ ‏ ‏كُرَيْبٍ ‏ ‏مَوْلَى ‏ ‏عَبْدِ اللَّهِ بْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏مَرَّ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى امْرَأَةٍ وَمَعَهَا صَبِيٌّ لَهَا فِي ‏ ‏مِحَفَّةٍ ‏ ‏فَأَخَذَتْ ‏ ‏بِضَبْعِهِ ‏ ‏فَقَالَتْ يَا رَسُولَ اللَّهِ أَلِهَذَا حَجٌّ قَالَ نَعَمْ وَلَكِ أَجْرٌ ‏","","",""],[2079,2079,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سِيرِينَ ‏ ‏أَنَّ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏حَدَّثَهُ قَالَ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَعَرَّقَ ‏ ‏كَتِفًا ثُمَّ قَامَ فَصَلَّى وَلَمْ يَتَوَضَّأْ ‏","","",""],[2080,2080,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِي التَّيَّاحِ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ سَلَمَةَ ‏ ‏قَالَ ‏ ‏خَرَجْتُ أَنَا ‏ ‏وَسِنَانُ بْنُ سَلَمَةَ ‏ ‏وَمَعَنَا ‏ ‏بَدَنَتَانِ ‏ ‏فَأَزْحَفَتَا ‏ ‏عَلَيْنَا فِي الطَّرِيقِ فَقَالَ لِي ‏ ‏سِنَانٌِ ‏ ‏هَلْ لَكَ فِي ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏فَأَتَيْنَاهُ فَسَأَلَهُ ‏ ‏سِنَانٌ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏ ‏قَالَ ‏ ‏وَقَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏سَأَلَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْجُهَنِيُّ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ إِنَّ أَبِي شَيْخٌ كَبِيرٌ لَمْ يَحُجَّ قَالَ ‏ ‏حُجَّ عَنْ أَبِيكَ ‏","","",""],[2081,2081,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏فُلَيْحٌ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ وَعْلَةَ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏فَقُلْتُ إِنَّا بِأَرْضٍ لَنَا بِهَا الْكُرُومُ وَإِنَّ أَكْثَرَ غَلَّاتِهَا الْخَمْرُ فَقَالَ قَدِمَ ‏ ‏رَجُلٌ ‏ ‏مِنْ ‏ ‏دَوْسٍ ‏ ‏عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِرَاوِيَةِ ‏ ‏خَمْرٍ أَهْدَاهَا لَهُ فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَلْ عَلِمْتَ أَنَّ اللَّهَ حَرَّمَهَا بَعْدَكَ فَأَقْبَلَ صَاحِبُ ‏ ‏الرَّاوِيَةِ ‏ ‏عَلَى إِنْسَانٍ مَعَهُ فَأَمَرَهُ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمَاذَا أَمَرْتَهُ قَالَ بِبَيْعِهَا قَالَ هَلْ عَلِمْتَ أَنَّ الَّذِي حَرَّمَ شُرْبَهَا حَرَّمَ بَيْعَهَا وَأَكْلَ ثَمَنِهَا قَالَ فَأَمَرَ ‏ ‏بِالْمَزَادَةِ ‏ ‏فَأُهْرِيقَتْ ‏","","",""],[2082,2082,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏وَحَسَنُ بْنُ مُوسَى ‏ ‏الْمَعْنَى ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏لَا أَعْلَمُهُ إِلَّا قَدْ رَفَعَهُ قَالَ كَانَ ‏ ‏إِذَا نَزَلَ مَنْزِلًا فَأَعْجَبَهُ الْمَنْزِلُ أَخَّرَ الظُّهْرَ حَتَّى يَجْمَعَ بَيْنَ الظُّهْرِ وَالْعَصْرِ وَإِذَا سَارَ وَلَمْ يَتَهَيَّأْ لَهُ الْمَنْزِلُ أَخَّرَ الظُّهْرَ حَتَّى يَأْتِيَ الْمَنْزِلَ فَيَجْمَعَ بَيْنَ الظُّهْرِ وَالْعَصْرِ ‏ ‏قَالَ ‏ ‏حَسَنٌ ‏ ‏كَانَ إِذَا سَافَرَ أَلِنَزَلَ مَنْزِلًا ‏","","",""],[2083,2083,"","","‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏أَبِي بِشْرٍ ‏ ‏عَنْ ‏ ‏مَيْمُونِ بْنِ مِهْرَانَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ كُلِّ ذِي ‏ ‏نَابٍ مِنْ السِّبَاعِ وَعَنْ كُلِّ ذِي مِخْلَبٍ مِنْ الطَّيْرِ ‏","","",""],[2084,2084,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ زَيْدٍ ‏ ‏عَنْ ‏ ‏كَثِيرِ بْنِ شِنْظِيرٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏إِنَّمَا كَانَ بَدْءُ ‏ ‏الْإِيضَاعِ ‏ ‏مِنْ قِبَلِ أَهْلِ الْبَادِيَةِ كَانُوا يَقِفُونَ حَافَتَيْ النَّاسِ حَتَّى يُعَلِّقُوا الْعِصِيَّ ‏ ‏وَالْجِعَابَ ‏ ‏وَالْقِعَابَ ‏ ‏فَإِذَا نَفَرُوا ‏ ‏تَقَعْقَعَتْ ‏ ‏تِلْكَ فَنَفَرُوا بِالنَّاسِ قَالَ وَلَقَدْ رُئِيَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَإِنَّ ‏ ‏ذِفْرَىْ نَاقَتِهِ لَيَمَسُّ ‏ ‏حَارِكَهَا ‏ ‏وَهُوَ يَقُولُ بِيَدِهِ يَا أَيُّهَا النَّاسُ ‏ ‏عَلَيْكُمْ ‏ ‏بِالسَّكِينَةِ ‏ ‏يَا أَيُّهَا النَّاسُ عَلَيْكُمْ ‏ ‏بِالسَّكِينَةِ ‏","","",""],[2085,2085,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏وَأَيُّوبَ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَامَ حَتَّى سُمِعَ لَهُ ‏ ‏غَطِيطٌ ‏ ‏فَقَامَ فَصَلَّى وَلَمْ يَتَوَضَّأْ ‏ ‏فَقَالَ ‏ ‏عِكْرِمَةُ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَحْفُوظًا ‏","","",""],[2086,2086,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏قَالَ ‏ ‏حَمَّادٌ ‏ ‏أَخْبَرَنَا ‏ ‏أَيُّوبُ ‏ ‏وَقَيْسٌ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ أَبِي رَبَاحٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَخَّرَ الْعِشَاءَ ذَاتَ لَيْلَةٍ حَتَّى نَامَ الْقَوْمُ ثُمَّ اسْتَيْقَظُوا ثُمَّ نَامُوا ثُمَّ اسْتَيْقَظُوا قَالَ ‏ ‏قَيْسٌ ‏ ‏فَجَاءَ ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏فَقَالَ الصَّلَاةَ يَا رَسُولَ اللَّهِ قَالَ ‏ ‏فَخَرَجَ فَصَلَّى بِهِمْ وَلَمْ يَذْكُرْ أَنَّهُمْ تَوَضَّئُوا ‏","","",""],[2087,2087,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏وَحَسَنٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏كُرَيْبِ بْنِ أَبِي مُسْلِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ فِي بَيْتِ ‏ ‏مَيْمُونَةَ بِنْتِ الْحَارِثِ ‏ ‏فَقَامَ ‏ ‏يُصَلِّي مِنْ اللَّيْلِ قَالَ فَقُمْتُ عَنْ يَسَارِهِ فَأَخَذَ بِيَدِي ‏ ‏فَأَقَامَنِي ‏ ‏عَنْ يَمِينِهِ ثُمَّ صَلَّى ثُمَّ نَامَ حَتَّى ‏ ‏نَفَخَ ‏ ‏ثُمَّ جَاءَهُ ‏ ‏بِلَالٌ ‏ ‏بِالْأَذَانِ فَقَامَ فَصَلَّى وَلَمْ يَتَوَضَّأْ ‏ ‏قَالَ ‏ ‏حَسَنٌ ‏ ‏يَعْنِي فِي حَدِيثِهِ ‏ ‏كُنْتُ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي بَيْتِ ‏ ‏مَيْمُونَةَ ‏ ‏فَلَمَّا قَضَى صَلَاتَهُ نَامَ حَتَّى ‏ ‏نَفَخَ ‏","","",""],[2088,2088,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَبِي الْعَالِيَةِ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عَمِّ نَبِيِّكُمْ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأَيْتُ لَيْلَةَ ‏ ‏أُسْرِيَ ‏ ‏بِي ‏ ‏مُوسَى بْنَ عِمْرَانَ ‏ ‏رَجُلًا ‏ ‏آدَمَ ‏ ‏طُوَالًا ‏ ‏جَعْدًا ‏ ‏كَأَنَّهُ مِنْ رِجَالِ ‏ ‏شَنُوءَةَ ‏ ‏وَرَأَيْتُ ‏ ‏عِيسَى ابْنَ مَرْيَمَ ‏ ‏عَلَيْهِمَا السَّلَام ‏ ‏مَرْبُوعَ ‏ ‏الْخَلْقِ إِلَى الْحُمْرَةِ وَالْبَيَاضِ ‏ ‏سَبْطَ ‏ ‏الرَّأْسِ ‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏فِي تَفْسِيرِ ‏ ‏شَيْبَانَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو الْعَالِيَةِ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عَمِّ نَبِيِّكُمْ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ مِثْلَهُ ‏","","",""],[2089,2089,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ رَبِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَبَّادُ بْنُ مَنْصُورٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَضَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ابْنِ ‏ ‏الْمُلَاعَنَةِ ‏ ‏أَنْ ‏ ‏لَا يُدْعَى لِأَبٍ وَمَنْ ‏ ‏رَمَاهَا ‏ ‏أَوْ ‏ ‏رَمَى ‏ ‏وَلَدَهَا فَإِنَّهُ يُجْلَدُ ‏ ‏الْحَدَّ ‏ ‏وَقَضَى أَنْ لَا ‏ ‏قُوتَ ‏ ‏لَهَا وَلَا سُكْنَى مِنْ أَجْلِ أَنَّهُمَا يَتَفَرَّقَانِ مِنْ غَيْرِ طَلَاقٍ وَلَا مُتَوَفًّى عَنْهَا ‏","","",""],[2090,2090,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَزَوَّجَ ‏ ‏مَيْمُونَةَ بِنْتَ الْحَارِثِ ‏ ‏وَهُمَا مُحْرِمَانِ ‏","","",""],[2091,2091,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَطَاءٍ الْعَطَّارِ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يَتَصَدَّقُ بِدِينَارٍ فَإِنْ لَمْ يَجِدْ فَنِصْفُ دِينَارٍ ‏ ‏يَعْنِي الَّذِي ‏ ‏يَغْشَى ‏ ‏امْرَأَتَهُ حَائِضًا ‏","","",""],[2092,2092,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏لَقِيَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَاعِزَ بْنَ مَالِكٍ ‏ ‏فَقَالَ أَحَقٌّ مَا بَلَغَنِي عَنْكَ قَالَ وَمَا بَلَغَكَ عَنِّي قَالَ ‏ ‏بَلَغَنِي أَنَّكَ ‏ ‏فَجَرْتَ ‏ ‏بِأَمَةِ آلِ فُلَانٍ قَالَ نَعَمْ فَرَدَّهُ حَتَّى شَهِدَ أَرْبَعَ مَرَّاتٍ ثُمَّ أَمَرَ ‏ ‏بِرَجْمِهِ ‏","","",""],[2093,2093,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَلِىِّ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏يُوسُفَ بْنِ مِهْرَانَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ ‏ ‏جِبْرِيلَ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏قَالَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْ رَأَيْتَنِي وَأَنَا آخُذُ مِنْ ‏ ‏حَالِ ‏ ‏الْبَحْرِ ‏ ‏فَأَدُسُّهُ ‏ ‏فِي ‏ ‏فِي ‏ ‏فِرْعَوْنَ ‏","","",""],[2094,2094,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏بَعَثَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏الثَّقَلِ ‏ ‏مِنْ ‏ ‏جَمْعٍ ‏ ‏بِلَيْلٍ ‏","","",""],[2095,2095,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏حَمَّادٍ يَعْنِي ابْنَ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏يُوسُفَ بْنِ مِهْرَانَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏قَالَ لِي ‏ ‏جِبْرِيلُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏إِنَّهُ قَدْ حُبِّبَ إِلَيْكَ الصَّلَاةُ فَخُذْ مِنْهَا مَا شِئْتَ ‏","","",""],[2096,2096,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏وَعَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏أَخْبَرَنَا ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏يُوسُفَ بْنِ مِهْرَانَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَجُلًا أَتَى ‏ ‏عُمَرَ ‏ ‏فَقَالَ امْرَأَةٌ جَاءَتْ ‏ ‏تُبَايِعُهُ ‏ ‏فَأَدْخَلْتُهَا ‏ ‏الدَّوْلَجَ ‏ ‏فَأَصَبْتُ مِنْهَا مَا دُونَ الْجِمَاعِ فَقَالَ ‏ ‏وَيْحَكَ ‏ ‏لَعَلَّهَا ‏ ‏مُغِيبٌ ‏ ‏فِي سَبِيلِ اللَّهِ قَالَ أَجَلْ قَالَ فَأْتِ ‏ ‏أَبَا بَكْرٍ ‏ ‏فَاسْأَلْهُ قَالَ فَأَتَاهُ فَسَأَلَهُ فَقَالَ لَعَلَّهَا ‏ ‏مُغِيبٌ ‏ ‏فِي سَبِيلِ اللَّهِ قَالَ فَقَالَ مِثْلَ قَوْلِ ‏ ‏عُمَرَ ‏ ‏ثُمَّ أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ لَهُ مِثْلَ ذَلِكَ قَالَ فَلَعَلَّهَا ‏ ‏مُغِيبٌ ‏ ‏فِي سَبِيلِ اللَّهِ وَنَزَلَ الْقُرْآنُ ‏ { ‏وَأَقِمْ الصَّلَاةَ طَرَفَيْ النَّهَارِ ‏ ‏وَزُلَفًا ‏ ‏مِنْ اللَّيْلِ إِنَّ الْحَسَنَاتِ يُذْهِبْنَ السَّيِّئَاتِ ‏} ‏إِلَى آخِرِ الْآيَةِ فَقَالَ يَا رَسُولَ اللَّهِ أَلِي خَاصَّةً أَمْ لِلنَّاسِ عَامَّةً فَضَرَبَ ‏ ‏عُمَرُ ‏ ‏صَدْرَهُ بِيَدِهِ فَقَالَ لَا وَلَا نَعْمَةَ عَيْنٍ بَلْ لِلنَّاسِ عَامَّةً فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَدَقَ ‏ ‏عُمَرُ ‏","","",""],[2097,2097,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏يُوسُفَ بْنِ مِهْرَانَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏جَاءَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَرَدِيفُهُ ‏ ‏أُسَامَةُ بْنُ زَيْدٍ ‏ ‏فَسَقَيْنَاهُ مِنْ هَذَا الشَّرَابِ فَقَالَ ‏ ‏أَحْسَنْتُمْ هَكَذَا فَاصْنَعُوا ‏","","",""],[2098,2098,"","","‏ ‏حَدَّثَنَا ‏ ‏مَرْوَانُ بْنُ شُجَاعٍ ‏ ‏قَالَ ‏ ‏مَا أَحْفَظُهُ إِلَّا ‏ ‏سَالِمٌ الْأَفْطَسُ الْجَزَرِيُّ ابْنُ عَجْلَانَ ‏ ‏حَدَّثَنِي عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الشِّفَاءُ فِي ثَلَاثَةٍ شَرْبَةِ عَسَلٍ وَشَرْطَةِ ‏ ‏مِحْجَمٍ ‏ ‏وَكَيَّةِ نَارٍ وَأَنْهَى أُمَّتِي عَنْ الْكَيِّ ‏","","",""],[2099,2099,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏حَدَّثَنِي ‏ ‏إِبْرَاهِيمُ يَعْنِي ابْنَ سَعْدٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏وَيَعْقُوبُ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏كَانَ الْمُشْرِكُونَ يَفْرُقُونَ رُءُوسَهُمْ وَكَانَ ‏ ‏أَهْلُ الْكِتَابِ ‏ ‏يَسْدِلُونَ ‏ ‏قَالَ ‏ ‏يَعْقُوبُ ‏ ‏أَشْعَارَهُمْ ‏ ‏وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُحِبُّ وَيُعْجِبُهُ مُوَافَقَةُ ‏ ‏أَهْلِ الْكِتَابِ ‏ ‏قَالَ ‏ ‏يَعْقُوبُ ‏ ‏فِي بَعْضِ مَا لَمْ يُؤْمَرْ ‏ ‏قَالَ ‏ ‏إِسْحَاقُ ‏ ‏فِيمَا لَمْ يُؤْمَرْ فِيهِ ‏ ‏فَسَدَلَ ‏ ‏نَاصِيَتَهُ ‏ ‏ثُمَّ ‏ ‏فَرَقَ ‏ ‏بَعْدُ ‏","","",""],[2100,2100,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏أَبُو خَيْثَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُثْمَانَ بْنِ خُثَيْمٍ ‏ ‏عَنْ ‏ ‏أَبِي الطُّفَيْلِ ‏ ‏قَالَ ‏ ‏رَأَيْتُ ‏ ‏مُعَاوِيَةَ ‏ ‏يَطُوفُ ‏ ‏بِالْبَيْتِ ‏ ‏عَنْ يَسَارِهِ ‏ ‏عَبْدُ اللَّهِ بْنُ عَبَّاسٍ ‏ ‏وَأَنَا ‏ ‏أَتْلُوهُمَا فِي ظُهُورِهِمَا أَسْمَعُ كَلَامَهُمَا ‏ ‏فَطَفِقَ ‏ ‏مُعَاوِيَةُ ‏ ‏يَسْتَلِمُ ‏ ‏رُكْنَ الْحَجَرَ فَقَالَ لَهُ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمْ ‏ ‏يَسْتَلِمْ ‏ ‏هَذَيْنِ الرُّكْنَيْنِ فَيَقُولُ ‏ ‏مُعَاوِيَةُ ‏ ‏دَعْنِي مِنْكَ يَا ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏فَإِنَّهُ لَيْسَ مِنْهَا شَيْءٌ مَهْجُورٌ ‏ ‏فَطَفِقَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏لَا يَزِيدُهُ كُلَّمَا وَضَعَ يَدَهُ عَلَى شَيْءٍ مِنْ الرُّكْنَيْنِ قَالَ لَهُ ذَلِكَ ‏","","",""],[2101,2101,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏دَاوُدُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏اعْتَمَرَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَرْبَعًا عُمْرَةً مِنْ ‏ ‏الْحُدَيْبِيَةِ ‏ ‏وَعُمْرَةَ الْقَضَاءِ فِي ذِي الْقَعْدَةِ مِنْ ‏ ‏قَابِلٍ ‏ ‏وَعُمْرَةَ الثَّالِثَةِ مِنْ ‏ ‏الْجِعِرَّانَةِ ‏ ‏وَالرَّابِعَةَ الَّتِي مَعَ حَجَّتِهِ ‏","","",""],[2102,2102,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ أَبِي الْعَبَّاسِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ بْنِ مَسْعُودٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ أَنْزَلَ ‏ { ‏وَمَنْ لَمْ يَحْكُمْ بِمَا أَنْزَلَ اللَّهُ فَأُولَئِكَ هُمْ الْكَافِرُونَ ‏} ‏وَ ‏ { ‏أُولَئِكَ هُمْ الظَّالِمُونَ ‏} ‏وَ ‏ { ‏أُولَئِكَ هُمْ الْفَاسِقُونَ ‏} ‏قَالَ قَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏أَنْزَلَهَا اللَّهُ فِي الطَّائِفَتَيْنِ مِنْ ‏ ‏الْيَهُودِ ‏ ‏وَكَانَتْ إِحْدَاهُمَا قَدْ قَهَرَتْ الْأُخْرَى فِي الْجَاهِلِيَّةِ حَتَّى ارْتَضَوْا ‏ ‏أَوْ اصْطَلَحُوا ‏ ‏عَلَى أَنَّ كُلَّ قَتِيلٍ قَتَلَهُ الْعَزِيزَةُ مِنْ الذَّلِيلَةِ ‏ ‏فَدِيَتُهُ ‏ ‏خَمْسُونَ ‏ ‏وَسْقًا ‏ ‏وَكُلَّ قَتِيلٍ قَتَلَهُ الذَّلِيلَةُ مِنْ الْعَزِيزَةِ ‏ ‏فَدِيَتُهُ ‏ ‏مِائَةُ ‏ ‏وَسْقٍ ‏ ‏فَكَانُوا عَلَى ذَلِكَ حَتَّى قَدِمَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَدِينَةَ ‏ ‏فَذَلَّتْ الطَّائِفَتَانِ كِلْتَاهُمَا لِمَقْدَمِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَيَوْمَئِذٍ لَمْ يَظْهَرْ وَلَمْ ‏ ‏يُوطِئْهُمَا ‏ ‏عَلَيْهِ وَهُوَ فِي الصُّلْحِ فَقَتَلَتْ الذَّلِيلَةُ مِنْ الْعَزِيزَةِ قَتِيلًا فَأَرْسَلَتْ الْعَزِيزَةُ إِلَى الذَّلِيلَةِ أَنْ ابْعَثُوا إِلَيْنَا بِمِائَةِ ‏ ‏وَسْقٍ ‏ ‏فَقَالَتْ الذَّلِيلَةُ وَهَلْ كَانَ هَذَا فِي حَيَّيْنِ قَطُّ دِينُهُمَا وَاحِدٌ وَنَسَبُهُمَا وَاحِدٌ وَبَلَدُهُمَا وَاحِدٌ ‏ ‏دِيَةُ ‏ ‏بَعْضِهِمْ نِصْفُ ‏ ‏دِيَةِ ‏ ‏بَعْضٍ إِنَّا إِنَّمَا أَعْطَيْنَاكُمْ هَذَا ‏ ‏ضَيْمًا ‏ ‏مِنْكُمْ لَنَا وَفَرَقًا مِنْكُمْ فَأَمَّا إِذْ قَدِمَ ‏ ‏مُحَمَّدٌ ‏ ‏فَلَا ‏ ‏نُعْطِيكُمْ ذَلِكَ فَكَادَتْ الْحَرْبُ تَهِيجُ بَيْنَهُمَا ثُمَّ ارْتَضَوْا عَلَى أَنْ يَجْعَلُوا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْنَهُمْ ثُمَّ ذَكَرَتْ الْعَزِيزَةُ فَقَالَتْ وَاللَّهِ مَا ‏ ‏مُحَمَّدٌ ‏ ‏بِمُعْطِيكُمْ مِنْهُمْ ضِعْفَ مَا ‏ ‏يُعْطِيهِمْ مِنْكُمْ وَلَقَدْ صَدَقُوا مَا أَعْطَوْنَا هَذَا إِلَّا ‏ ‏ضَيْمًا ‏ ‏مِنَّا وَقَهْرًا لَهُمْ فَدُسُّوا إِلَى ‏ ‏مُحَمَّدٍ ‏ ‏مَنْ يَخْبُرُ لَكُمْ رَأْيَهُ إِنْ أَعْطَاكُمْ مَا تُرِيدُونَ حَكَّمْتُمُوهُ وَإِنْ لَمْ يُعْطِكُمْ حَذِرْتُمْ فَلَمْ تُحَكِّمُوهُ فَدَسُّوا إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَاسًا مِنْ الْمُنَافِقِينَ لِيَخْبُرُوا لَهُمْ رَأْيَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمَّا جَاءَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَخْبَرَ اللَّهُ رَسُولَهُ بِأَمْرِهِمْ كُلِّهِ وَمَا أَرَادُوا فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏ { ‏يَا أَيُّهَا الرَّسُولُ لَا يَحْزُنْكَ الَّذِينَ يُسَارِعُونَ فِي الْكُفْرِ مِنْ الَّذِينَ قَالُوا آمَنَّا ‏ ‏إِلَى قَوْلِهِ ‏ ‏وَمَنْ لَمْ يَحْكُمْ بِمَا أَنْزَلَ اللَّهُ فَأُولَئِكَ هُمْ الْفَاسِقُونَ ‏} ‏ثُمَّ قَالَ فِيهِمَا وَاللَّهِ نَزَلَتْ وَإِيَّاهُمَا عَنَى اللَّهُ عَزَّ وَجَلَّ ‏","","",""],[2103,2103,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَاصِمٍ ‏ ‏أَخْبَرَنَا ‏ ‏خَالِدٌ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ يَسْتَمِعْ إِلَى حَدِيثِ قَوْمٍ وَهُمْ لَهُ كَارِهُونَ صُبَّ فِي أُذُنِهِ ‏ ‏الْآنُكُ ‏ ‏وَمَنْ ‏ ‏تَحَلَّمَ ‏ ‏عُذِّبَ حَتَّى ‏ ‏يَعْقِدَ ‏ ‏شَعِيرَةً وَلَيْسَ بِعَاقِدٍ وَمَنْ صَوَّرَ صُورَةً كُلِّفَ أَنْ يَنْفُخَ فِيهَا وَلَيْسَ بِنَافِخٍ ‏","","",""],[2104,2104,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَاصِمٍ ‏ ‏أَخْبَرَنَا ‏ ‏مُعَاوِيَةُ بْنُ عَمْرِو بْنِ غَلَابٍ ‏ ‏عَنِ ‏ ‏الْحَكَمِ بْنِ عَبْدِ اللَّهِ بْنِ الْأَعْرَجِ ‏ ‏قَالَ ‏ ‏كُنْتُ عِنْدَ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏فِي بَيْتِ ‏ ‏السِّقَايَةِ ‏ ‏وَهُوَ ‏ ‏مُتَوَسِّدٌ ‏ ‏بُرْدًا ‏ ‏لَهُ قَالَ فَقُلْتُ يَا ‏ ‏أَبَا عَبَّاسٍ ‏ ‏أَخْبِرْنِي عَنْ ‏ ‏عَاشُورَاءَ ‏ ‏قَالَ عَنْ أَيِّ ‏ ‏بَالِهِ ‏ ‏قَالَ قُلْتُ عَنْ صِيَامِهِ قَالَ ‏ ‏إِذَا أَنْتَ ‏ ‏أَهْلَلْتَ ‏ ‏الْمُحَرَّمَ فَاعْدُدْ تِسْعًا ثُمَّ أَصْبِحْ يَوْمَ التَّاسِعِ صَائِمًا قُلْتُ كَذَا كَانَ يَصُومُهُ ‏ ‏مُحَمَّدٌ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ نَعَمْ ‏","","",""],[2105,2105,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَاصِمٍ ‏ ‏أَخْبَرَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ عُثْمَانَ بْنِ خُثَيْمٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَأْتِي هَذَا الْحَجَرُ يَوْمَ الْقِيَامَةِ لَهُ عَيْنَانِ يُبْصِرُ بِهِمَا وَلِسَانٌ يَنْطِقُ بِهِ يَشْهَدُ لِمَنْ ‏ ‏اسْتَلَمَهُ ‏ ‏بِحَقٍّ ‏","","",""],[2106,2106,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَاصِمٍ ‏ ‏قَالَ قَالَ ‏ ‏دَاوُدُ ‏ ‏حَدَّثَنَا ‏ ‏عِكْرِمَةُ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏كَانَ نَاسٌ مِنْ الْأَسْرَى يَوْمَ ‏ ‏بَدْرٍ ‏ ‏لَمْ يَكُنْ لَهُمْ فِدَاءٌ ‏ ‏فَجَعَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِدَاءَهُمْ أَنْ يُعَلِّمُوا أَوْلَادَ ‏ ‏الْأَنْصَارِ ‏ ‏الْكِتَابَةَ قَالَ فَجَاءَ يَوْمًا غُلَامٌ يَبْكِي إِلَى أَبِيهِ فَقَالَ مَا شَأْنُكَ قَالَ ضَرَبَنِي مُعَلِّمِي قَالَ الْخَبِيثُ يَطْلُبُ ‏ ‏بِذَحْلِ ‏ ‏بَدْرٍ ‏ ‏وَاللَّهِ لَا تَأْتِيهِ أَبَدًا ‏","","",""],[2107,2107,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَاصِمٍ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ السَّائِبِ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏أَمَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ ‏ ‏أُحُدٍ ‏ ‏بِالشُّهَدَاءِ أَنْ يُنْزَعَ عَنْهُمْ الْحَدِيدُ وَالْجُلُودُ وَقَالَ ادْفِنُوهُمْ بِدِمَائِهِمْ وَثِيَابِهِمْ ‏","","",""],[2108,2108,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَاصِمٍ ‏ ‏عَنْ ‏ ‏دَاوُدَ بْنِ أَبِي هِنْدٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَجُلًا مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏ارْتَدَّ عَنْ الْإِسْلَامِ وَلَحِقَ بِالْمُشْرِكِينَ فَأَنْزَلَ اللَّهُ تَعَالَى ‏ { ‏كَيْفَ يَهْدِي اللَّهُ قَوْمًا كَفَرُوا بَعْدَ إِيمَانِهِمْ ‏} ‏إِلَى آخِرِ الْآيَةِ فَبَعَثَ بِهَا قَوْمُهُ فَرَجَعَ تَائِبًا فَقَبِلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَلِكَ مِنْهُ وَخَلَّى عَنْهُ ‏","","",""],[2109,2109,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيٌّ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ عُثْمَانَ بْنِ خُثَيْمٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْبَسُوا مِنْ ثِيَابِكُمْ الْبَيَاضَ فَإِنَّهَا مِنْ خَيْرِ ثِيَابِكُمْ وَكَفِّنُوا فِيهَا مَوْتَاكُمْ وَإِنَّ مِنْ خَيْرِ ‏ ‏أَكْحَالِكُمُ ‏ ‏الْإِثْمِدَ ‏ ‏يَجْلُو ‏ ‏الْبَصَرَ وَيُنْبِتُ الشَّعَرَ ‏","","",""],[2110,2110,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَاصِمٍ ‏ ‏عَنِ ‏ ‏الْجُرَيْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي الطُّفَيْلِ ‏ ‏وَعَبْدِ اللَّهِ بْنِ عُثْمَانَ بْنِ خُثَيْمٍ ‏ ‏عَنْ ‏ ‏أَبِي الطُّفَيْلِ ‏ ‏كِلَاهُمَا ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏رَمَلَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثَلَاثَةَ أَشْوَاطٍ ‏ ‏بِالْبَيْتِ ‏ ‏إِذَا انْتَهَى إِلَى الرُّكْنِ الْيَمَانِي وَمَشَى حَتَّى يَأْتِيَ الْحَجَرَ ثُمَّ ‏ ‏يَرْمُلُ ‏ ‏وَمَشَى أَرْبَعَةَ أَطْوَافٍ قَالَ قَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏وَكَانَتْ سُنَّةً ‏","","",""],[2111,2111,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَاصِمٍ ‏ ‏أَخْبَرَنَا ‏ ‏الْحَذَّاءُ ‏ ‏عَنْ ‏ ‏بَرَكَةَ أَبِي الْوَلِيدِ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَاعِدًا فِي ‏ ‏الْمَسْجِدِ ‏ ‏مُسْتَقْبِلًا الْحُجَرَ قَالَ فَنَظَرَ إِلَى السَّمَاءِ فَضَحِكَ ثُمَّ قَالَ ‏ ‏لَعَنَ اللَّهُ ‏ ‏الْيَهُودَ ‏ ‏حُرِّمَتْ عَلَيْهِمْ الشُّحُومُ فَبَاعُوهَا وَأَكَلُوا أَثْمَانَهَا وَإِنَّ اللَّهَ عَزَّ وَجَلَّ إِذَا حَرَّمَ عَلَى قَوْمٍ أَكْلَ شَيْءٍ حَرَّمَ عَلَيْهِمْ ثَمَنَهُ ‏","","",""],[2112,2112,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَاصِمٍ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الْمُعَلَّى الْعَطَّارُ ‏ ‏حَدَّثَنَا ‏ ‏الْحَسَنُ الْعُرَنِيُّ ‏ ‏قَالَ ‏ ‏ذُكِرَ عِنْدَ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏يَقْطَعُ الصَّلَاةَ الْكَلْبُ وَالْحِمَارُ وَالْمَرْأَةُ قَالَ بِئْسَمَا عَدَلْتُمْ بِامْرَأَةٍ مُسْلِمَةٍ كَلْبًا وَحِمَارًا لَقَدْ رَأَيْتُنِي ‏ ‏أَقْبَلْتُ عَلَى حِمَارٍ وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي بِالنَّاسِ حَتَّى إِذَا كُنْتُ قَرِيبًا مِنْهُ مُسْتَقْبِلَهُ نَزَلْتُ عَنْهُ وَخَلَّيْتُ عَنْهُ وَدَخَلْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي صَلَاتِهِ فَمَا أَعَادَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَاتَهُ وَلَا نَهَانِي عَمَّا صَنَعْتُ وَلَقَدْ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي بِالنَّاسِ فَجَاءَتْ ‏ ‏وَلِيدَةٌ ‏ ‏تَخَلَّلُ ‏ ‏الصُّفُوفَ حَتَّى عَاذَتْ بِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَمَا أَعَادَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَاتَهُ وَلَا نَهَاهَا عَمَّا صَنَعَتْ وَلَقَدْ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي فِي مَسْجِدٍ فَخَرَجَ جَدْيٌ مِنْ بَعْضِ حُجُرَاتِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَهَبَ يَجْتَازُ بَيْنَ يَدَيْهِ فَمَنَعَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏أَفَلَا تَقُولُونَ الْجَدْيُ يَقْطَعُ الصَّلَاةَ ‏","","",""],[2113,2113,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مَيْمُونٍ أَبُو عَبْدِ الرَّحْمَنِ الرَّقِّيُّ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏الْحَسَنُ يَعْنِي أَبَا الْمَلِيحِ ‏ ‏عَنْ ‏ ‏حَبِيبٍ يَعْنِي ابْنَ أَبِي مَرْزُوقٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏مَنْ قَدِمَ حَاجًّا وَطَافَ ‏ ‏بِالْبَيْتِ ‏ ‏وَبَيْنَ ‏ ‏الصَّفَا ‏ ‏وَالْمَرْوَةِ ‏ ‏فَقَدْ انْقَضَتْ ‏ ‏حَجَّتُهُ وَصَارَتْ عُمْرَةً كَذَلِكَ سُنَّةُ اللَّهِ عَزَّ وَجَلَّ وَسُنَّةُ رَسُولِهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[2114,2114,"","","‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ الْحُبَابِ ‏ ‏أَخْبَرَنَا ‏ ‏سَيْفٌ ‏ ‏أَخْبَرَنَا ‏ ‏قَيْسُ بْنُ سَعْدٍ الْمَكِّيُّ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَضَى بِشَاهِدٍ وَيَمِينٍ ‏","","",""],[2115,2115,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ يَزِيدَ الرَّقِّيُّ أَبُو يَزِيدَ ‏ ‏حَدَّثَنَا ‏ ‏فُرَاتٌ ‏ ‏عَنْ ‏ ‏عَبْدِ الْكَرِيمِ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏أَبُو جَهْلٍ ‏ ‏لَئِنْ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي عِنْدَ ‏ ‏الْكَعْبَةِ ‏ ‏لَآتِيَنَّهُ حَتَّى ‏ ‏أَطَأَ ‏ ‏عَلَى عُنُقِهِ قَالَ فَقَالَ ‏ ‏لَوْ فَعَلَ لَأَخَذَتْهُ الْمَلَائِكَةُ عِيَانًا وَلَوْ أَنَّ ‏ ‏الْيَهُودَ ‏ ‏تَمَنَّوْا الْمَوْتَ لَمَاتُوا وَرَأَوْا مَقَاعِدَهُمْ فِي النَّارِ وَلَوْ خَرَجَ الَّذِينَ ‏ ‏يُبَاهِلُونَ ‏ ‏رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَرَجَعُوا لَا يَجِدُونَ مَالًا وَلَا أَهْلًا ‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ عَبْدِ الْمَلِكِ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏عَبْدِ الْكَرِيمِ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏أَبُو جَهْلٍ ‏ ‏فَذَكَرَ مَعْنَاهُ ‏","","",""],[2116,2116,"","","‏ ‏حَدَّثَنَا ‏ ‏نَصْرُ بْنُ بَابٍ أَبُو سَهْلٍ ‏ ‏فِي شَوَّالٍ سَنَةَ إِحْدَى وَثَمَانِينَ وَمِائَةٍ ‏ ‏عَنِ ‏ ‏الْحَجَّاجِ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏مِقْسَمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏طَافَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالْبَيْتِ ‏ ‏وَجَعَلَ ‏ ‏يَسْتَلِمُ ‏ ‏الْحَجَرَ ‏ ‏بِمِحْجَنِهِ ‏ ‏ثُمَّ أَتَى ‏ ‏السِّقَايَةَ ‏ ‏بَعْدَمَا فَرَغَ وَبَنُو عَمِّهِ يَنْزِعُونَ مِنْهَا فَقَالَ نَاوِلُونِي فَرُفِعَ لَهُ الدَّلْوُ فَشَرِبَ ثُمَّ قَالَ ‏ ‏لَوْلَا أَنَّ النَّاسَ يَتَّخِذُونَهُ ‏ ‏نُسُكًا ‏ ‏وَيَغْلِبُونَكُمْ عَلَيْهِ لَنَزَعْتُ مَعَكُمْ ثُمَّ خَرَجَ فَطَافَ بَيْنَ ‏ ‏الصَّفَا ‏ ‏وَالْمَرْوَةِ ‏","","",""],[2117,2117,"","","‏ ‏حَدَّثَنَا ‏ ‏نَصْرُ بْنُ بَابٍ ‏ ‏عَنِ ‏ ‏الْحَجَّاجِ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏مِقْسَمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏احْتَجَمَ ‏ ‏صَائِمًا مُحْرِمًا فَغُشِيَ عَلَيْهِ قَالَ فَلِذَلِكَ كَرِهَ ‏ ‏الْحِجَامَةَ ‏ ‏لِلصَّائِمِ ‏","","",""],[2118,2118,"","","‏ ‏حَدَّثَنَا ‏ ‏نَصْرُ بْنُ بَابٍ ‏ ‏عَنِ ‏ ‏الْحَجَّاجِ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏مِقْسَمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ ‏ ‏الطَّائِفِ ‏ ‏مَنْ خَرَجَ إِلَيْنَا مِنْ الْعَبِيدِ فَهُوَ حُرٌّ فَخَرَجَ عَبِيدٌ مِنْ الْعَبِيدِ فِيهِمْ ‏ ‏أَبُو بَكْرَةَ ‏ ‏فَأَعْتَقَهُمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[2119,2119,"","","‏ ‏حَدَّثَنَا ‏ ‏نَصْرُ بْنُ بَابٍ ‏ ‏قَالَ ثَنَا ‏ ‏الْحَجَّاجُ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏مِقْسَمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏قَتَلَ الْمُسْلِمُونَ يَوْمَ ‏ ‏الْخَنْدَقِ ‏ ‏رَجُلًا مِنْ الْمُشْرِكِينَ فَأَعْطَوْا ‏ ‏بِجِيفَتِهِ ‏ ‏مَالًا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ادْفَعُوا إِلَيْهِمْ ‏ ‏جِيفَتَهُمْ ‏ ‏فَإِنَّهُ ‏ ‏خَبِيثُ ‏ ‏الْجِيفَةِ ‏ ‏خَبِيثُ ‏ ‏الدِّيَةِ ‏ ‏فَلَمْ يَقْبَلْ مِنْهُمْ شَيْئًا ‏","","",""],[2120,2120,"","","‏ ‏حَدَّثَنَا ‏ ‏نَصْرُ بْنُ بَابٍ ‏ ‏حَدَّثَنَا ‏ ‏الْحَجَّاجُ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏مِقْسَمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏رَمَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْجِمَارَ ‏ ‏عِنْدَ زَوَالِ الشَّمْسِ ‏ ‏أَوْ بَعْدَ زَوَالِ الشَّمْسِ ‏","","",""],[2121,2121,"","","‏ ‏حَدَّثَنَا ‏ ‏نَصْرُ بْنُ بَابٍ ‏ ‏عَنِ ‏ ‏الْحَجَّاجِ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏مِقْسَمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِنَّ أَهْلَ ‏ ‏بَدْرٍ ‏ ‏كَانُوا ثَلَاثَ مِائَةٍ وَثَلَاثَةَ عَشَرَ رَجُلًا وَكَانَ ‏ ‏الْمُهَاجِرُونَ ‏ ‏سِتَّةً وَسَبْعِينَ وَكَانَ هَزِيمَةُ أَهْلِ ‏ ‏بَدْرٍ ‏ ‏لِسَبْعَ عَشْرَةَ مَضَيْنَ يَوْمَ الْجُمُعَةِ فِي شَهْرِ رَمَضَانَ ‏","","",""],[2122,2122,"","","‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏وَجَدْتُ فِي كِتَابِ أَبِي بِخَطِّ يَدِهِ ‏ ‏حَدَّثَنَا ‏ ‏مَهْدِيُّ بْنُ جَعْفَرٍ الرَّمْلِيُّ ‏ ‏حَدَّثَنَا ‏ ‏الْوَلِيدُ يَعْنِي ابْنَ مُسْلِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اسْمَحْ يُسْمَحْ لَكَ ‏","","",""],[2123,2123,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏وَجَدْتُ فِي كِتَابِ أَبِي بِخَطِّ يَدِهِ ‏ ‏حَدَّثَنَا ‏ ‏مَهْدِيُّ بْنُ جَعْفَرٍ الرَّمْلِيُّ ‏ ‏حَدَّثَنَا ‏ ‏الْوَلِيدُ يَعْنِي ابْنَ مُسْلِمٍ ‏ ‏عَنِ ‏ ‏الْحَكَمِ بْنِ مُصْعَبٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَلِيِّ بْنِ عَبْدِ اللَّهِ بْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أَكْثَرَ مِنْ ‏ ‏الِاسْتِغْفَارِ جَعَلَ اللَّهُ لَهُ مِنْ كُلِّ هَمٍّ فَرَجًا وَمِنْ كُلِّ ضِيقٍ مَخْرَجًا وَرَزَقَهُ مِنْ حَيْثُ لَا ‏ ‏يَحْتَسِبُ ‏","","",""],[2124,2124,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏أَخْبَرَنَا ‏ ‏جَرِيرُ بْنُ حَازِمٍ ‏ ‏أَخْبَرَنَا ‏ ‏قَيْسُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ هُرْمُزَ ‏ ‏قَالَ ‏ ‏كَتَبَ ‏ ‏نَجْدَةُ بْنُ عَامِرٍ ‏ ‏إِلَى ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏يَسْأَلُهُ عَنْ أَشْيَاءَ فَشَهِدْتُ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏حِينَ قَرَأَ كِتَابَهُ وَحِينَ كَتَبَ جَوَابَهُ فَقَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏وَاللَّهِ لَوْلَا أَنْ أَرُدَّهُ عَنْ شَرٍّ يَقَعُ فِيهِ مَا كَتَبْتُ إِلَيْهِ وَلَا نَعْمَةَ عَيْنٍ قَالَ فَكَتَبَ إِلَيْهِ إِنَّكَ ‏ ‏سَأَلْتَنِي عَنْ سَهْمِ ‏ ‏ذَوِي ‏ ‏الْقُرْبَى الَّذِي ذَكَرَ اللَّهُ عَزَّ وَجَلَّ مَنْ هُمْ وَإِنَّا كُنَّا نُرَى قَرَابَةَ رَسُولِ اللَّهِ هُمْ فَأَبَى ذَلِكَ عَلَيْنَا قَوْمُنَا وَسَأَلَهُ عَنْ الْيَتِيمِ مَتَى ‏ ‏يَنْقَضِي يُتْمُهُ وَإِنَّهُ إِذَا بَلَغَ النِّكَاحَ ‏ ‏وَأُونِسَ ‏ ‏مِنْهُ رُشْدٌ دُفِعَ إِلَيْهِ مَالُهُ وَقَدْ انْقَضَى يُتْمُهُ وَسَأَلَهُ هَلْ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْتُلُ مِنْ صِبْيَانِ الْمُشْرِكِينَ أَحَدًا فَقَالَ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمْ يَقْتُلْ مِنْهُمْ أَحَدًا وَأَنْتَ فَلَا تَقْتُلْ إِلَّا أَنْ تَكُونَ تَعْلَمُ مَا عَلِمَ ‏ ‏الْخَضِرُ ‏ ‏مِنْ الْغُلَامِ الَّذِي قَتَلَهُ وَسَأَلَهُ عَنْ الْمَرْأَةِ وَالْعَبْدِ هَلْ كَانَ لَهُمَا سَهْمٌ مَعْلُومٌ إِذَا حَضَرُوا ‏ ‏الْبَأْسَ ‏ ‏وَإِنَّهُ لَمْ يَكُنْ لَهُمْ سَهْمٌ مَعْلُومٌ إِلَّا أَنْ يُحْذَيَا مِنْ غَنَائِمِ الْمُسْلِمِينَ ‏","","",""],[2125,2125,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏أَخْبَرَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏عَمَّارِ بْنِ أَبِي عَمَّارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَخْطُبُ إِلَى جِذْعٍ قَبْلَ أَنْ يَتَّخِذَ الْمِنْبَرَ فَلَمَّا اتَّخَذَ الْمِنْبَرَ وَتَحَوَّلَ إِلَيْهِ حَنَّ عَلَيْهِ فَأَتَاهُ فَاحْتَضَنَهُ فَسَكَنَ قَالَ ‏ ‏وَلَوْ لَمْ أَحْتَضِنْهُ لَحَنَّ إِلَى يَوْمِ الْقِيَامَةِ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ ‏","","",""],[2126,2126,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ سَالِمٍ أَبُو جَهْضَمٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ عُبَيْدِ اللَّهِ بْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏دَخَلْتُ أَنَا وَفِتْيَةٌ مِنْ ‏ ‏قُرَيْشٍ ‏ ‏عَلَى ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ فَسَأَلُوهُ هَلْ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْرَأُ فِي الظُّهْرِ وَالْعَصْرِ قَالَ لَا قَالَ فَقَالُوا فَلَعَلَّهُ كَانَ يَقْرَأُ فِي نَفْسِهِ قَالَ ‏ ‏خَمْشًا ‏ ‏هَذِهِ شَرٌّ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ عَبْدًا مَأْمُورًا بَلَّغَ مَا أُرْسِلَ بِهِ وَإِنَّهُ لَمْ يَخُصَّنَا دُونَ النَّاسِ إِلَّا بِثَلَاثٍ ‏ ‏أَمَرَنَا أَنْ ‏ ‏نُسْبِغَ ‏ ‏الْوُضُوءَ وَلَا نَأْكُلَ ‏ ‏الصَّدَقَةَ ‏ ‏وَلَا ‏ ‏نُنْزِيَ ‏ ‏حِمَارًا عَلَى فَرَسٍ ‏","","",""],[2127,2127,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَحَّلَ نَاسًا مِنْ ‏ ‏بَنِي هَاشِمٍ ‏ ‏بِلَيْلٍ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏أَحْسَبُهُ قَالَ ضَعَفَتَهُمْ ‏ ‏وَأَمَرَهُمْ أَنْ ‏ ‏لَا يَرْمُوا الْجَمْرَةَ حَتَّى تَطْلُعَ الشَّمْسُ ‏ ‏شُعْبَةُ ‏ ‏شَكَّ فِي ضَعَفَتَهُمْ ‏","","",""],[2128,2128,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏ابْنُ طَاوُسٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏وَقَّتَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِأَهْلِ ‏ ‏الْمَدِينَةِ ‏ ‏ذَا الْحُلَيْفَةِ ‏ ‏وَلِأَهْلِ ‏ ‏الشَّامِ ‏ ‏الْجُحْفَةَ ‏ ‏وَلِأَهْلِ ‏ ‏نَجْدٍ ‏ ‏قَرْنًا ‏ ‏وَلِأَهْلِ ‏ ‏الْيَمَنِ ‏ ‏يَلَمْلَمَ ‏ ‏قَالَ هُنَّ لَهُمْ وَلِمَنْ أَتَى عَلَيْهِمْ مِمَّنْ سِوَاهُمْ مِمَّنْ أَرَادَ الْحَجَّ وَالْعُمْرَةَ مِنْ حَيْثُ ‏ ‏بَدَأَ ‏ ‏حَتَّى يَبْلُغَ ذَلِكَ أَهْلَ ‏ ‏مَكَّةَ ‏","","",""],[2129,2129,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَقِيقٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُصِيبُ مِنْ الرُّءُوسِ وَهُوَ صَائِمٌ ‏","","",""],[2130,2130,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏أُنْزِلَ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ابْنُ أَرْبَعِينَ وَكَانَ ‏ ‏بِمَكَّةَ ‏ ‏ثَلَاثَ عَشْرَةَ ‏ ‏وَبِالْمَدِينَةِ ‏ ‏عَشْرًا فَمَاتَ وَهُوَ ابْنُ ثَلَاثٍ وَسِتِّينَ ‏","","",""],[2131,2131,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏احْتَجَمَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏احْتِجَامَةً ‏ ‏فِي رَأْسِهِ وَهُوَ ‏ ‏مُحْرِمٌ ‏","","",""],[2132,2132,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَاصِمٍ الْأَحْوَلِ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَعَا بِشَرَابٍ قَالَ فَأَتَيْتُهُ بِدَلْوٍ مِنْ مَاءِ ‏ ‏زَمْزَمَ ‏ ‏فَشَرِبَ قَائِمًا ‏","","",""],[2133,2133,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّهُ أَتَى خَالَتَهُ ‏ ‏مَيْمُونَةَ زَوْجَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏فَقَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ اللَّيْلِ إِلَى ‏ ‏سِقَايَةٍ ‏ ‏فَتَوَضَّأَ ثُمَّ قَامَ فَصَلَّى قَالَ وَقُمْتُ فَتَوَضَّأْتُ ثُمَّ قُمْتُ عَنْ يَسَارِهِ قَالَ فَأَخَذَ بِيَدِي فَأَدَارَنِي مِنْ خَلْفِهِ حَتَّى أَقَامَنِي عَنْ يَمِينِهِ ‏","","",""],[2134,2134,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجُ بْنُ النُّعْمَانِ ‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏حُصَيْنٌ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَدْ ‏ ‏حَفِظْتُ السُّنَّةَ كُلَّهَا غَيْرَ أَنِّي لَا أَدْرِي أَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْرَأُ فِي الظُّهْرِ وَالْعَصْرِ أَمْ لَا وَلَا أَدْرِي كَيْفَ كَانَ يَقْرَأُ هَذَا الْحَرْفَ ‏ { ‏وَقَدْ بَلَغْتُ مِنْ الْكِبَرِ ‏ ‏عُتِيًّا ‏ } ‏أَوْ ‏ ‏عُسُيًّا ‏","","",""],[2135,2135,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا بْنُ إِسْحَاقَ ‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ دِينَارٍ ‏ ‏أَنَّ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏كَانَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يُبَاعُ الثَّمَرُ حَتَّى ‏ ‏يُطْعَمَ ‏","","",""],[2136,2136,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدُ بْنُ الْحَارِثِ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي نَهِيكٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ اسْتَعَاذَ بِاللَّهِ فَأَعِيذُوهُ وَمَنْ سَأَلَكُمْ بِوَجْهِ اللَّهِ فَأَعْطُوهُ ‏","","",""],[2137,2137,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو دَاوُدَ ‏ ‏عَنْ ‏ ‏زَمْعَةَ ‏ ‏عَنِ ‏ ‏ابْنِ طَاوُسٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏احْتَجَمَ ‏ ‏وَأَعْطَى ‏ ‏الْحَجَّامَ ‏ ‏أَجْرَهُ ‏","","",""],[2138,2138,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏طَاوُسٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْعُمْرَى ‏ ‏لِمَنْ ‏ ‏أُعْمِرَهَا ‏ ‏وَالرُّقْبَى ‏ ‏لِمَنْ ‏ ‏أُرْقِبَهَا ‏ ‏وَالْعَائِدُ فِي هِبَتِهِ كَالْعَائِدِ فِي قَيْئِهِ ‏","","",""],[2139,2139,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏طَاوُسٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ ‏ ‏أَعْمَرَ ‏ ‏عُمْرَى ‏ ‏فَهِيَ لِمَنْ ‏ ‏أُعْمِرَهَا ‏ ‏جَائِزَةٌ ‏ ‏وَمَنْ ‏ ‏أَرْقَبَ ‏ ‏رُقْبَى ‏ ‏فَهِيَ لِمَنْ ‏ ‏أُرْقِبَهَا ‏ ‏جَائِزَةٌ ‏ ‏وَمَنْ وَهَبَ هِبَةً ثُمَّ عَادَ فِيهَا فَهُوَ كَالْعَائِدِ فِي قَيْئِهِ ‏","","",""],[2140,2140,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ عَلِيٍّ ‏ ‏عَنْ ‏ ‏زَائِدَةَ ‏ ‏عَنْ ‏ ‏سِمَاكِ بْنِ حَرْبٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏صَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَصْحَابُهُ إِلَى ‏ ‏بَيْتِ الْمَقْدِسِ ‏ ‏سِتَّةَ عَشَرَ شَهْرًا ثُمَّ صُرِفَتْ الْقِبْلَةُ بَعْدُ ‏","","",""],[2141,2141,"","","‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ الْحَجَّاجِ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ الْمُبَارَكِ ‏ ‏أَخْبَرَنَا ‏ ‏الْحَجَّاجُ بْنُ أَرْطَاةَ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏أَبِي الْقَاسِمِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏رَمَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَمْرَةَ الْعَقَبَةِ ‏ ‏ثُمَّ ذَبَحَ ثُمَّ حَلَقَ ‏","","",""],[2142,2142,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنِى ‏ ‏مُحَمَّدُ بْنُ الْوَلِيدِ بْنِ نُوَيْفِعٍ ‏ ‏مَوْلَى آلِ ‏ ‏الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏كُرَيْبٍ ‏ ‏مَوْلَى ‏ ‏عَبْدِ اللَّهِ بْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبَّاسٍ ‏ ‏أَنَّ ‏ ‏ضِمَامَ بْنَ ثَعْلَبَةَ ‏ ‏أَخَا ‏ ‏بَنِي سَعْدِ بْنِ بَكْرٍ ‏ ‏لَمَّا أَسْلَمَ سَأَلَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ فَرَائِضِ الْإِسْلَامِ مِنْ الصَّلَاةِ وَغَيْرِهَا ‏ ‏فَعَدَّ عَلَيْهِ الصَّلَوَاتِ الْخَمْسَ لَمْ يَزِدْ عَلَيْهِنَّ ثُمَّ الزَّكَاةَ ثُمَّ صِيَامَ رَمَضَانَ ثُمَّ حَجَّ ‏ ‏الْبَيْتِ ‏ ‏ثُمَّ أَعْلَمَهُ مَا حَرَّمَ اللَّهُ عَلَيْهِ فَلَمَّا فَرَغَ قَالَ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَشْهَدُ أَنَّكَ رَسُولُ اللَّهِ وَسَأَفْعَلُ مَا أَمَرْتَنِي بِهِ لَا أَزِيدُ وَلَا أَنْقُصُ قَالَ ثُمَّ ‏ ‏وَلَّى ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنْ يَصْدُقْ ذُو ‏ ‏الْعَقِيصَتَيْنِ ‏ ‏يَدْخُلْ الْجَنَّةَ ‏","","",""],[2143,2143,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجُ بْنُ النُّعْمَانِ ‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي لَيْلَى ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏مِقْسَمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَفَعَ ‏ ‏خَيْبَرَ ‏ ‏أَرْضَهَا وَنَخْلَهَا مُقَاسَمَةً عَلَى النِّصْفِ ‏","","",""],[2144,2144,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَاصِمٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي زِيَادٍ ‏ ‏عَنْ ‏ ‏مِقْسَمٍ ‏ ‏وَمُجَاهِدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُعْطِيتُ خَمْسًا لَمْ يُعْطَهُنَّ أَحَدٌ قَبْلِي وَلَا أَقُولُهُ فَخْرًا ‏ ‏بُعِثْتُ إِلَى كُلِّ أَحْمَرَ وَأَسْوَدَ فَلَيْسَ مِنْ أَحْمَرَ وَلَا أَسْوَدَ يَدْخُلُ فِي أُمَّتِي إِلَّا كَانَ مِنْهُمْ وَجُعِلَتْ لِي الْأَرْضُ مَسْجِدًا ‏","","",""],[2145,2145,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ يَعْنِي الدَّبَّاغَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ الدَّانَاجِ ‏ ‏حَدَّثَنَا ‏ ‏عِكْرِمَةُ ‏ ‏مَوْلَى ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏صَلَّيْتُ خَلْفَ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ فَكَانَ ‏ ‏إِذَا رَكَعَ وَإِذَا سَجَدَ كَبَّرَ قَالَ فَذَكَرْتُ ذَلِكَ ‏ ‏لِابْنِ عَبَّاسٍ ‏ ‏فَقَالَ لَا أُمَّ لَكَ أَوَلَيْسَتْ تِلْكَ سُنَّةَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[2146,2146,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ الْجَزَّارِ ‏ ‏قَالَ قَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏مَرَّتْ ‏ ‏جَارِيَتَانِ ‏ ‏مِنْ ‏ ‏بَنِي هَاشِمٍ ‏ ‏فَجَاءَتَا إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ‏ ‏يُصَلِّي فَأَخَذَتَا بِرُكْبَتَيْهِ فَلَمْ يَنْصَرِفْ قَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏وَمَرَرْتُ أَنَا وَرَجُلٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ‏ ‏يُصَلِّي وَنَحْنُ عَلَى حِمَارٍ فَجِئْنَا فَدَخَلْنَا فِي الصَّلَاةِ ‏","","",""],[2147,2147,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏أَخْبَرَنَا ‏ ‏خَالِدٌ الْحَذَّاءُ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏حَمَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعْضَ غِلْمَةِ ‏ ‏بَنِي عَبْدِ الْمُطَّلِبِ ‏ ‏وَاحِدًا خَلْفَهُ وَوَاحِدًا بَيْنَ يَدَيْهِ ‏","","",""],[2148,2148,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَمَّرُ بْنُ سُلَيْمَانَ الرَّقِّيُّ ‏ ‏عَنِ ‏ ‏الْحَجَّاجِ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا نِكَاحَ إِلَّا ‏ ‏بِوَلِيٍّ ‏ ‏وَالسُّلْطَانُ ‏ ‏وَلِيُّ ‏ ‏مَنْ لَا ‏ ‏وَلِيَّ ‏ ‏لَهُ ‏ ‏حَدَّثَنَا ‏ ‏مُعَمَّرُ بْنُ سُلَيْمَانَ الرَّقِّيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ ‏","","",""],[2149,2149,"","","‏ ‏حَدَّثَنَا ‏ ‏مَرْوَانُ بْنُ مُعَاوِيَةَ الْفَزَارِيُّ ‏ ‏حَدَّثَنَا ‏ ‏حُمَيْدُ بْنُ عَلِيٍّ الْعُقَيْلِيُّ ‏ ‏حَدَّثَنَا ‏ ‏الضَّحَّاكُ بْنُ مُزَاحِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏صَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ سَافَرَ رَكْعَتَيْنِ وَحِينَ أَقَامَ أَرْبَعًا قَالَ قَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏فَمَنْ صَلَّى فِي السَّفَرِ أَرْبَعًا كَمَنْ صَلَّى فِي الْحَضَرِ رَكْعَتَيْنِ قَالَ وَقَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏لَمْ تُقْصَرْ الصَّلَاةُ إِلَّا مَرَّةً حَيْثُ صَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَكْعَتَيْنِ وَصَلَّى النَّاسُ رَكْعَةً رَكْعَةً ‏","","",""],[2150,2150,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَعَنَ ‏ ‏الْوَاصِلَةَ ‏ ‏وَالْمَوْصُولَةَ ‏ ‏وَالْمُتَشَبِّهِينَ مِنْ الرِّجَالِ بِالنِّسَاءِ وَالْمُتَشَبِّهَاتِ مِنْ النِّسَاءِ بِالرِّجَالِ ‏","","",""],[2151,2151,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عُمَرَ ‏ ‏حَدَّثَنَا ‏ ‏الْمَسْعُودِيُّ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏مِقْسَمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏لَمَّا ‏ ‏أَفَاضَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ ‏ ‏عَرَفَاتٍ ‏ ‏أَوْضَعَ ‏ ‏النَّاسُ فَأَمَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُنَادِيًا يُنَادِي أَيُّهَا النَّاسُ ‏ ‏لَيْسَ الْبِرُّ ‏ ‏بِإِيضَاعِ ‏ ‏الْخَيْلِ وَلَا ‏ ‏الرِّكَابِ ‏ ‏قَالَ فَمَا رَأَيْتُ مِنْ رَافِعَةٍ يَدَهَا ‏ ‏عَادِيَةً ‏ ‏حَتَّى نَزَلَ ‏ ‏جَمْعًا ‏","","",""],[2152,2152,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عُمَرَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ ‏ ‏أُسَامَةَ بْنَ زَيْدٍ ‏ ‏كَانَ ‏ ‏رِدْفَ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ ‏ ‏عَرَفَةَ ‏ ‏فَدَخَلَ ‏ ‏الشِّعْبَ ‏ ‏فَنَزَلَ ‏ ‏فَأَهْرَاقَ ‏ ‏الْمَاءَ ثُمَّ تَوَضَّأَ وَرَكِبَ وَلَمْ يُصَلِّ ‏","","",""],[2153,2153,"","","‏ ‏حَدَّثَنَا ‏ ‏سَعْدُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏صَالِحٍ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏أَنَّ ‏ ‏سُلَيْمَانَ بْنَ يَسَارٍ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ امْرَأَةً مِنْ ‏ ‏خَثْعَمَ ‏ ‏اسْتَفْتَتْ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي حَجَّةِ الْوَدَاعِ ‏ ‏وَالْفَضْلُ بْنُ عَبَّاسٍ ‏ ‏رَدِيفُ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ يَا رَسُولَ اللَّهِ ‏ ‏إِنَّ فَرِيضَةَ اللَّهِ فِي الْحَجِّ أَدْرَكَتْ أَبِي شَيْخًا كَبِيرًا لَا يَسْتَطِيعُ أَنْ يَسْتَوِيَ عَلَى ‏ ‏الرَّاحِلَةِ ‏ ‏فَهَلْ يَقْضِي عَنْهُ أَنْ أَحُجَّ عَنْهُ فَقَالَ لَهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَعَمْ فَأَخَذَ ‏ ‏الْفَضْلُ بْنُ عَبَّاسٍ ‏ ‏يَلْتَفِتُ إِلَيْهَا وَكَانَتْ امْرَأَةً حَسْنَاءَ فَأَخَذَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْفَضْلَ ‏ ‏فَحَوَّلَ وَجْهَهُ مِنْ ‏ ‏الشِّقِّ ‏ ‏الْآخَرِ ‏","","",""],[2154,2154,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ حَسَنٍ الْأَشْقَرُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو كُدَيْنَةَ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏أَبِي الضُّحَى ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏مَرَّ يَهُودِيٌّ بِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ جَالِسٌ قَالَ كَيْفَ تَقُولُ يَا ‏ ‏أَبَا الْقَاسِمِ ‏ ‏يَوْمَ يَجْعَلُ اللَّهُ السَّمَاءَ عَلَى ذِهْ وَأَشَارَ بِالسَّبَّابَةِ وَالْأَرْضَ عَلَى ذِهْ وَالْمَاءَ عَلَى ذِهْ وَالْجِبَالَ عَلَى ذِهْ وَسَائِرَ الْخَلْقِ عَلَى ذِهْ كُلُّ ذَلِكَ يُشِيرُ بِأَصَابِعِهِ قَالَ فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏ { ‏وَمَا قَدَرُوا اللَّهَ حَقَّ قَدْرِهِ ‏}","","",""],[2155,2155,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ الْأَشْقَرُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو كُدَيْنَةَ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏أَبِي الضُّحَى ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏أَصْبَحَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَاتَ يَوْمٍ وَلَيْسَ فِي الْعَسْكَرِ مَاءٌ فَأَتَاهُ رَجُلٌ فَقَالَ يَا رَسُولَ اللَّهِ لَيْسَ فِي الْعَسْكَرِ مَاءٌ قَالَ هَلْ عِنْدَكَ شَيْءٌ قَالَ نَعَمْ قَالَ فَأْتِنِي بِهِ قَالَ فَأَتَاهُ بِإِنَاءٍ فِيهِ شَيْءٌ مِنْ مَاءٍ قَلِيلٍ قَالَ ‏ ‏فَجَعَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَصَابِعَهُ فِي فَمِ الْإِنَاءِ وَفَتَحَ أَصَابِعَهُ قَالَ فَانْفَجَرَتْ مِنْ بَيْنِ أَصَابِعِهِ عُيُونٌ وَأَمَرَ ‏ ‏بِلَالًا ‏ ‏فَقَالَ نَادِ فِي النَّاسِ الْوَضُوءَ الْمُبَارَكَ ‏","","",""],[2156,2156,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ زَيْدٍ ‏ ‏عَنِ ‏ ‏الزُّبَيْرِ يَعْنِي ابْنَ خِرِّيتٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَقِيقٍ ‏ ‏قَالَ ‏ ‏خَطَبَنَا ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏يَوْمًا بَعْدَ الْعَصْرِ حَتَّى غَرَبَتْ الشَّمْسُ وَبَدَتْ النُّجُومُ وَعَلِقَ النَّاسُ يُنَادُونَهُ الصَّلَاةَ وَفِي الْقَوْمِ رَجُلٌ مِنْ ‏ ‏بَنِي تَمِيمٍ ‏ ‏فَجَعَلَ يَقُولُ الصَّلَاةَ الصَّلَاةَ قَالَ فَغَضِبَ قَالَ أَتُعَلِّمُنِي بِالسُّنَّةِ شَهِدْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَمَعَ بَيْنَ الظُّهْرِ وَالْعَصْرِ وَالْمَغْرِبِ وَالْعِشَاءِ ‏ ‏قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏فَوَجَدْتُ فِي نَفَسِي مِنْ ذَلِكَ شَيْئًا فَلَقِيتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏فَسَأَلْتُهُ ‏ ‏فَوَافَقَهُ ‏","","",""],[2157,2157,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏يُوسُفَ بْنِ مِهْرَانَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّهُ ‏ ‏قَالَ ‏ ‏لَمَّا نَزَلَتْ ‏ ‏آيَةُ الدَّيْنِ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ أَوَّلَ مَنْ ‏ ‏جَحَدَ ‏ ‏آدَمُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏أَوْ أَوَّلُ مَنْ ‏ ‏جَحَدَ ‏ ‏آدَمُ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ لَمَّا خَلَقَ ‏ ‏آدَمَ ‏ ‏مَسَحَ ظَهْرَهُ فَأَخْرَجَ مِنْهُ مَا هُوَ مِنْ ‏ ‏ذَرَارِيَّ ‏ ‏إِلَى يَوْمِ الْقِيَامَةِ ‏ ‏فَجَعَلَ يَعْرِضُ ذُرِّيَّتَهُ عَلَيْهِ فَرَأَى فِيهِمْ رَجُلًا يَزْهَرُ فَقَالَ أَيْ رَبِّ مَنْ هَذَا قَالَ هَذَا ابْنُكَ ‏ ‏دَاوُدُ ‏ ‏قَالَ أَيْ رَبِّ كَمْ عُمْرُهُ قَالَ سِتُّونَ عَامًا قَالَ رَبِّ زِدْ فِي عُمْرِهِ قَالَ لَا إِلَّا أَنْ أَزِيدَهُ مِنْ عُمْرِكَ وَكَانَ عُمْرُ ‏ ‏آدَمَ ‏ ‏أَلْفَ عَامٍ فَزَادَهُ أَرْبَعِينَ عَامًا فَكَتَبَ اللَّهُ عَزَّ وَجَلَّ عَلَيْهِ بِذَلِكَ كِتَابًا وَأَشْهَدَ عَلَيْهِ الْمَلَائِكَةَ فَلَمَّا ‏ ‏احْتُضِرَ ‏ ‏آدَمُ ‏ ‏وَأَتَتْهُ الْمَلَائِكَةُ ‏ ‏لِتَقْبِضَهُ ‏ ‏قَالَ إِنَّهُ قَدْ بَقِيَ مِنْ عُمُرِي أَرْبَعُونَ عَامًا فَقِيلَ إِنَّكَ قَدْ وَهَبْتَهَا لِابْنِكَ ‏ ‏دَاوُدَ ‏ ‏قَالَ مَا فَعَلْتُ وَأَبْرَزَ اللَّهُ عَزَّ وَجَلَّ عَلَيْهِ الْكِتَابَ وَشَهِدَتْ عَلَيْهِ الْمَلَائِكَةُ ‏","","",""],[2158,2158,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بِشْرٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏مَا قَرَأَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى الْجِنِّ وَلَا رَآهُمْ انْطَلَقَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي طَائِفَةٍ مِنْ أَصْحَابِهِ عَامِدِينَ إِلَى سُوقِ ‏ ‏عُكَاظٍ ‏ ‏وَقَدْ حِيلَ بَيْنَ الشَّيَاطِينِ وَبَيْنَ خَبَرِ السَّمَاءِ وَأُرْسِلَتْ عَلَيْهِمْ الشُّهُبُ قَالَ فَرَجَعَتْ الشَّيَاطِينُ إِلَى قَوْمِهِمْ فَقَالُوا مَا لَكُمْ قَالُوا حِيلَ بَيْنَنَا وَبَيْنَ خَبَرِ السَّمَاءِ وَأُرْسِلَتْ عَلَيْنَا الشُّهُبُ قَالَ فَقَالُوا مَا حَالَ بَيْنَكُمْ وَبَيْنَ خَبَرِ السَّمَاءِ إِلَّا شَيْءٌ حَدَثَ فَاضْرِبُوا مَشَارِقَ الْأَرْضِ وَمَغَارِبَهَا فَانْظُرُوا مَا هَذَا الَّذِي حَالَ بَيْنَكُمْ وَبَيْنَ خَبَرِ السَّمَاءِ قَالَ فَانْطَلَقُوا يَضْرِبُونَ مَشَارِقَ الْأَرْضِ وَمَغَارِبَهَا يَبْتَغُونَ مَا هَذَا الَّذِي حَالَ بَيْنَهُمْ وَبَيْنَ خَبَرِ السَّمَاءِ قَالَ فَانْصَرَفَ النَّفَرُ الَّذِينَ تَوَجَّهُوا نَحْوَ ‏ ‏تِهَامَةَ ‏ ‏إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ‏ ‏بِنَخْلَةَ ‏ ‏عَامِدًا إِلَى سُوقِ ‏ ‏عُكَاظٍ ‏ ‏وَهُوَ ‏ ‏يُصَلِّي بِأَصْحَابِهِ صَلَاةَ الْفَجْرِ قَالَ فَلَمَّا سَمِعُوا الْقُرْآنَ اسْتَمَعُوا لَهُ وَقَالُوا هَذَا وَاللَّهِ الَّذِي حَالَ بَيْنَكُمْ وَبَيْنَ خَبَرِ السَّمَاءِ قَالَ فَهُنَالِكَ حِينَ رَجَعُوا إِلَى قَوْمِهِمْ فَقَالُوا يَا قَوْمَنَا ‏ { ‏إِنَّا سَمِعْنَا قُرْآنًا عَجَبًا يَهْدِي إِلَى الرُّشْدِ فَآمَنَّا بِهِ ‏} ‏الْآيَةَ ‏ ‏فَأَنْزَلَ اللَّهُ عَلَى نَبِيِّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ { ‏قُلْ أُوحِيَ إِلَيَّ أَنَّهُ ‏} ‏وَإِنَّمَا أُوحِيَ إِلَيْهِ قَوْلُ الْجِنِّ ‏","","",""],[2159,2159,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ طَاوُسٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَّتَ لِأَهْلِ ‏ ‏الْمَدِينَةِ ‏ ‏ذَا الْحُلَيْفَةِ ‏ ‏وَلِأَهْلِ ‏ ‏الشَّامِ ‏ ‏الْجُحْفَةَ ‏ ‏وَلِأَهْلِ ‏ ‏نَجْدٍ ‏ ‏قَرْنَ الْمَنَازِلِ ‏ ‏وَلِأَهْلِ ‏ ‏الْيَمَنِ ‏ ‏يَلَمْلَمَ ‏ ‏هُنَّ لَهُمْ وَلِكُلِّ آتٍ أَتَى عَلَيْهِنَّ مِنْ غَيْرِهِنَّ مِمَّنْ أَرَادَ الْحَجَّ وَالْعُمْرَةَ فَمَنْ كَانَ مِنْ دُونِ ذَلِكَ فَمِنْ حَيْثُ ‏ ‏أَنْشَأَ ‏ ‏حَتَّى أَهْلُ ‏ ‏مَكَّةَ ‏ ‏مِنْ ‏ ‏مَكَّةَ ‏","","",""],[2160,2160,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ طَاوُسٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَكَحَ ‏ ‏مَيْمُونَةَ ‏ ‏وَهُوَ مُحْرِمٌ ‏","","",""],[2161,2161,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ طَاوُسٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏كَانُوا يَرَوْنَ الْعُمْرَةَ فِي أَشْهُرِ الْحَجِّ مِنْ أَفْجَرِ الْفُجُورِ فِي الْأَرْضِ وَيَجْعَلُونَ الْمُحَرَّمَ صَفَرًا وَيَقُولُونَ إِذَا ‏ ‏بَرَأَ ‏ ‏الدَّبَرْ ‏ ‏وَعَفَا ‏ ‏الْأَثَرْ ‏ ‏وَانْسَلَخَ ‏ ‏صَفَرْ حَلَّتْ الْعُمْرَةُ لِمَنْ ‏ ‏اعْتَمَرْ فَلَمَّا قَدِمَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَصْحَابُهُ لِصَبِيحَةِ رَابِعَةٍ ‏ ‏مُهِلِّينَ ‏ ‏بِالْحَجِّ فَأَمَرَهُمْ أَنْ يَجْعَلُوهَا عُمْرَةً ‏ ‏فَتَعَاظَمَ ‏ ‏ذَلِكَ عِنْدَهُمْ فَقَالُوا يَا رَسُولَ اللَّهِ أَيُّ الْحِلِّ قَالَ ‏ ‏الْحِلُّ كُلُّهُ وَفِي كِتَابِهِ لِصُبْحٍ ‏","","",""],[2162,2162,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ طَاوُسٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى أَنْ يَبِيعَ الرَّجُلُ طَعَامًا حَتَّى ‏ ‏يَسْتَوْفِيَهُ ‏ ‏قَالَ فَقُلْتُ لَهُ كَيْفَ ذَلِكَ قَالَ ذَلِكَ دَرَاهِمُ بِدَرَاهِمَ وَالطَّعَامُ ‏ ‏مُرْجَأٌ ‏","","",""],[2163,2163,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ طَاوُسٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ بْنِ خَالِدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَامَ مِنْ اللَّيْلِ ‏ ‏يُصَلِّي فَقُمْتُ فَتَوَضَّأْتُ فَقُمْتُ عَنْ يَسَارِهِ فَجَذَبَنِي فَجَرَّنِي فَأَقَامَنِي عَنْ يَمِينِهِ فَصَلَّى ثَلَاثَ عَشْرَةَ رَكْعَةً قِيَامُهُ فِيهِنَّ سَوَاءٌ ‏","","",""],[2164,2164,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي مُلَيْكَةَ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏عُرْوَةُ ‏ ‏لِابْنِ عَبَّاسٍ ‏ ‏حَتَّى مَتَى تُضِلُّ النَّاسَ يَا ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏قَالَ مَا ذَاكَ يَا ‏ ‏عُرَيَّةُ ‏ ‏قَالَ ‏ ‏تَأْمُرُنَا بِالْعُمْرَةِ فِي أَشْهُرِ الْحَجِّ وَقَدْ نَهَى ‏ ‏أَبُو بَكْرٍ ‏ ‏وَعُمَرُ ‏ ‏فَقَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏قَدْ فَعَلَهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏عُرْوَةُ ‏ ‏كَانَا هُمَا أَتْبَعَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَعْلَمَ بِهِ مِنْكَ ‏","","",""],[2165,2165,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏أَخْبَرَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ ‏ ‏عُقْبَةَ بْنَ عَامِرٍ ‏ ‏أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ إِنَّ أُخْتَهُ ‏ ‏نَذَرَتْ ‏ ‏أَنْ تَمْشِيَ إِلَى ‏ ‏الْبَيْتِ ‏ ‏فَقَالَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ لَغَنِيٌّ عَنْ ‏ ‏نَذْرِ ‏ ‏أُخْتِكَ لِتَحُجَّ رَاكِبَةً ‏ ‏وَلْتُهْدِ ‏ ‏بَدَنَةً ‏","","",""],[2166,2166,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدٌ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ حَرَّمَ ‏ ‏مَكَّةَ ‏ ‏فَلَمْ تَحِلَّ لِأَحَدٍ كَانَ قَبْلِي وَلَا تَحِلُّ لِأَحَدٍ بَعْدِي وَإِنَّمَا أُحِلَّتْ لِي سَاعَةً مِنْ نَهَارٍ لَا يُخْتَلَى خَلَاهَا وَلَا ‏ ‏يُعْضَدُ ‏ ‏شَجَرُهَا وَلَا يُنَفَّرُ صَيْدُهَا وَلَا ‏ ‏تُلْتَقَطُ ‏ ‏لُقَطَتُهَا إِلَّا لِمُعَرِّفٍ فَقَالَ ‏ ‏الْعَبَّاسُ ‏ ‏إِلَّا ‏ ‏الْإِذْخِرَ ‏ ‏لِصَاغَتِنَا وَقُبُورِنَا قَالَ إِلَّا ‏ ‏الْإِذْخِرَ ‏","","",""],[2167,2167,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ السَّائِبِ ‏ ‏عَنْ ‏ ‏أَبِي يَحْيَى ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَجُلَيْنِ اخْتَصَمَا إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَأَلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمُدَّعِيَ ‏ ‏الْبَيِّنَةَ ‏ ‏فَلَمْ يَكُنْ لَهُ ‏ ‏بَيِّنَةٌ ‏ ‏فَاسْتَحْلَفَ الْمَطْلُوبَ فَحَلَفَ بِاللَّهِ الَّذِي لَا إِلَهَ إِلَّا هُوَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّكَ قَدْ فَعَلْتَ وَلَكِنْ غُفِرَ لَكَ بِإِخْلَاصِكَ قَوْلَ لَا إِلَهَ إِلَّا اللَّهُ ‏","","",""],[2168,2168,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏الْمُغِيرَةُ بْنُ النُّعْمَانِ ‏ ‏شَيْخٌ مِنْ ‏ ‏النَّخَعِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سَعِيدَ بْنَ جُبَيْرٍ ‏ ‏يُحَدِّثُ قَالَ سَمِعْتُ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَامَ فِينَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمَوْعِظَةٍ فَقَالَ يَا أَيُّهَا النَّاسُ ‏ ‏إِنَّكُمْ مَحْشُورُونَ إِلَى اللَّهِ حُفَاةً عُرَاةً ‏ ‏غُرْلًا ‏ { ‏كَمَا بَدَأْنَا أَوَّلَ خَلْقٍ نُعِيدُهُ وَعْدًا عَلَيْنَا إِنَّا كُنَّا فَاعِلِينَ ‏} ‏أَلَا وَإِنَّ أَوَّلَ الْخَلْقِ ‏ ‏يُكْسَى يَوْمَ الْقِيَامَةِ ‏ ‏إِبْرَاهِيمُ ‏ ‏وَإِنَّهُ سَيُجَاءُ بِأُنَاسٍ مِنْ أُمَّتِي فَيُؤْخَذُ بِهِمْ ذَاتَ الشِّمَالِ فَلَأَقُولَنَّ أَصْحَابِي فَلَيُقَالَنَّ لِي إِنَّكَ لَا تَدْرِي مَا ‏ ‏أَحْدَثُوا ‏ ‏بَعْدَكَ فَلَأَقُولَنَّ كَمَا قَالَ الْعَبْدُ الصَّالِحُ ‏ { ‏وَكُنْتُ عَلَيْهِمْ شَهِيدًا مَا دُمْتُ فِيهِمْ فَلَمَّا تَوَفَّيْتَنِي كُنْتَ أَنْتَ الرَّقِيبَ عَلَيْهِمْ وَأَنْتَ عَلَى كُلِّ شَيْءٍ شَهِيدٌ ‏ ‏إِلَى ‏ ‏فَإِنَّهُمْ عِبَادُكَ وَإِنْ تَغْفِرْ لَهُمْ فَإِنَّكَ أَنْتَ الْعَزِيزُ الْحَكِيمُ ‏} ‏فَيُقَالُ إِنَّ هَؤُلَاءِ لَمْ يَزَالُوا مُرْتَدِّينَ عَلَى ‏ ‏أَعْقَابِهِمْ ‏ ‏مُنْذُ فَارَقْتَهُمْ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏أَمَلَّهُ عَلَى ‏ ‏سُفْيَانَ ‏ ‏فَأَمَلَّهُ عَلَيَّ ‏ ‏سُفْيَانُ ‏ ‏مَكَانَهُ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏الْمُغِيرَةِ بْنِ النُّعْمَانِ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَامَ فِينَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمَوْعِظَةٍ ‏ ‏فَذَكَرَهُ ‏","","",""],[2169,2169,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بِشْرٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏إِنَّ الَّذِي تَدْعُونَهُ ‏ ‏الْمُفَصَّلَ ‏ ‏هُوَ ‏ ‏الْمُحْكَمُ ‏ ‏تُوُفِّيَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنَا ابْنُ عَشْرِ سِنِينَ وَقَدْ قَرَأْتُ ‏ ‏الْمُحْكَمَ ‏","","",""],[2170,2170,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ ‏ ‏حَدَّثَنَا ‏ ‏الْحَجَّاجُ بْنُ أَرْطَاةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو جَعْفَرٍ مُحَمَّدُ بْنُ عَلِيٍّ ‏ ‏قَالَ ‏ ‏يَعْنِي ‏ ‏حَجَّاجًا ‏ ‏وَحَدَّثَنِي ‏ ‏الْحَكَمُ ‏ ‏عَنْ ‏ ‏مِقْسَمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كُفِّنَ فِي ثَوْبَيْنِ أَبْيَضَيْنِ وَفِي ‏ ‏بُرْدٍ ‏ ‏أَحْمَرَ ‏","","",""],[2171,2171,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏أَخْبَرَنَا ‏ ‏عَطَاءُ بْنُ السَّائِبِ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ ‏ ‏إِبْرَاهِيمَ ‏ ‏جَاءَ ‏ ‏بِإِسْمَاعِيلَ ‏ ‏عَلَيْهِمَا السَّلَام ‏ ‏وَهَاجَرَ ‏ ‏فَوَضَعَهُمَا ‏ ‏بِمَكَّةَ ‏ ‏فِي مَوْضِعِ ‏ ‏زَمْزَمَ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏ ‏ثُمَّ جَاءَتْ مِنْ ‏ ‏الْمَرْوَةِ ‏ ‏إِلَى ‏ ‏إِسْمَاعِيلَ ‏ ‏وَقَدْ نَبَعَتْ الْعَيْنُ فَجَعَلَتْ تَفْحَصُ الْعَيْنَ بِيَدِهَا هَكَذَا حَتَّى اجْتَمَعَ الْمَاءُ مِنْ ‏ ‏شَقِّهِ ‏ ‏ثُمَّ تَأْخُذُهُ بِقَدَحِهَا فَتَجْعَلُهُ فِي ‏ ‏سِقَائِهَا ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَرْحَمُهَا اللَّهُ لَوْ تَرَكَتْهَا لَكَانَتْ عَيْنًا سَائِحَةً ‏ ‏تَجْرِي إِلَى يَوْمِ الْقِيَامَةِ ‏","","",""],[2172,2172,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ عُقْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرِو بْنِ عَطَاءٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏يَقُولُ ‏ ‏إِنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَكَلَ إِمَّا ذِرَاعًا مَشْوِيًّا ‏ ‏وَإِمَّا كَتِفًا ‏ ‏ثُمَّ صَلَّى وَلَمْ يَتَوَضَّأْ وَلَمْ يَمَسَّ مَاءً ‏","","",""],[2173,2173,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدٌ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ أَبِي زِيَادٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَدِمْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حُجَّاجًا فَأَمَرَهُمْ فَجَعَلُوهَا عُمْرَةً ثُمَّ قَالَ ‏ ‏لَوْ ‏ ‏اسْتَقْبَلْتُ ‏ ‏مِنْ أَمْرِي مَا ‏ ‏اسْتَدْبَرْتُ ‏ ‏لَفَعَلْتُ كَمَا فَعَلُوا وَلَكِنْ دَخَلَتْ الْعُمْرَةُ فِي الْحَجِّ إِلَى يَوْمِ الْقِيَامَةِ ثُمَّ ‏ ‏أَنْشَبَ ‏ ‏أَصَابِعَهُ بَعْضَهَا فِي بَعْضٍ ‏ ‏فَحَلَّ ‏ ‏النَّاسُ إِلَّا مَنْ كَانَ مَعَهُ ‏ ‏هَدْيٌ ‏ ‏وَقَدِمَ ‏ ‏عَلِيٌّ ‏ ‏مِنْ ‏ ‏الْيَمَنِ ‏ ‏فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمَ ‏ ‏أَهْلَلْتَ ‏ ‏قَالَ ‏ ‏أَهْلَلْتُ ‏ ‏بِمَا ‏ ‏أَهْلَلْتَ ‏ ‏بِهِ قَالَ فَهَلْ مَعَكَ ‏ ‏هَدْيٌ ‏ ‏قَالَ لَا قَالَ فَأَقِمْ كَمَا أَنْتَ وَلَكَ ثُلُثُ ‏ ‏هَدْيِي ‏ ‏قَالَ وَكَانَ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِائَةُ ‏ ‏بَدَنَةٍ ‏","","",""],[2174,2174,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏فَرْقَدٍ السَّبَخِيِّ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ امْرَأَةً جَاءَتْ بِابْنٍ لَهَا إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ يَا رَسُولَ اللَّهِ إِنَّ ابْنِي هَذَا بِهِ جُنُونٌ وَإِنَّهُ يَأْخُذُهُ عِنْدَ غَدَائِنَا وَعَشَائِنَا فَيُفْسِدُ عَلَيْنَا ‏ ‏فَمَسَحَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَدْرَهُ وَدَعَا ‏ ‏فَثَعَّ ‏ ‏ثَعَّةً ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏فَسَأَلْتُ أَعْرَابِيًّا فَقَالَ بَعْضُهُ عَلَى أَثَرِ بَعْضٍ وَخَرَجَ مِنْ جَوْفِهِ مِثْلُ ‏ ‏الْجَرْوِ ‏ ‏الْأَسْوَدِ وَشُفِيَ ‏","","",""],[2175,2175,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏انْتَشَلَ مِنْ قِدْرٍ عَظْمًا فَصَلَّى وَلَمْ يَتَوَضَّأْ ‏","","",""],[2176,2176,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ الْعَطَّارُ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏زَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَّامٍ ‏ ‏عَنِ ‏ ‏الْحَكَمِ بْنِ مِينَاءَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏وَعَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّهُمَا سَمِعَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَيَنْتَهِيَنَّ أَقْوَامٌ عَنْ ‏ ‏وَدْعِهِمْ ‏ ‏الْجُمُعَاتِ أَوْ ‏ ‏لَيَخْتِمَنَّ ‏ ‏اللَّهُ عَلَى قُلُوبِهِمْ ثُمَّ لَيُكْتَبُنَّ مِنْ الْغَافِلِينَ ‏","","",""],[2177,2177,"","","‏ ‏حَدَّثَنَا ‏ ‏خَلَفُ بْنُ الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدٌ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي زِيَادٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏لَعَنَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمُخَنَّثِينَ ‏ ‏مِنْ الرِّجَالِ ‏ ‏وَالْمُتَرَجِّلَاتِ ‏ ‏مِنْ النِّسَاءِ قَالَ فَقُلْتُ مَا الْمُتَرَجِّلَاتُ مِنْ النِّسَاءِ قَالَ الْمُتَشَبِّهَاتُ مِنْ النِّسَاءِ بِالرِّجَالِ ‏","","",""],[2178,2178,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى عَلَى ‏ ‏النَّجَاشِيِّ ‏","","",""],[2179,2179,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏حَدَّثَنَا ‏ ‏بُكَيْرُ بْنُ الْأَخْنَسِ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏فَرَضَ اللَّهُ الصَّلَاةَ عَلَى لِسَانِ نَبِيِّكُمْ فِي الْحَضَرِ أَرْبَعًا وَفِي السَّفَرِ رَكْعَتَيْنِ وَفِي الْخَوْفِ رَكْعَةً ‏","","",""],[2180,2180,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ ‏ ‏أَخْبَرَنَا ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏يُوسُفَ بْنِ مِهْرَانَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا مِنْ أَحَدٍ مِنْ وَلَدِ ‏ ‏آدَمَ ‏ ‏إِلَّا قَدْ أَخْطَأَ أَوْ هَمَّ بِخَطِيئَةٍ لَيْسَ ‏ ‏يَحْيَى بْنَ زَكَرِيَّا ‏ ‏وَمَا يَنْبَغِي لِأَحَدٍ أَنْ يَقُولَ أَنَا خَيْرٌ مِنْ ‏ ‏يُونُسَ بْنِ مَتَّى ‏ ‏عَلَيْهِ السَّلَام ‏","","",""],[2181,2181,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ الْجَزَّارِ ‏ ‏أَنَّ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏مَرَرْتُ أَنَا وَغُلَامٌ مِنْ ‏ ‏بَنِي هَاشِمٍ ‏ ‏عَلَى حِمَارٍ وَتَرَكْنَاهُ يَأْكُلُ مِنْ بَقْلٍ بَيْنَ يَدَيْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمْ يَنْصَرِفْ وَجَاءَتْ ‏ ‏جَارِيَتَانِ ‏ ‏تَشْتَدَّانِ ‏ ‏حَتَّى أَخَذَتَا بِرُكْبَتَيْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمْ يَنْصَرِفْ ‏","","",""],[2182,2182,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏قَتَادَةُ ‏ ‏أَخْبَرَنِي قَالَ سَمِعْتُ ‏ ‏أَبَا حَسَّانَ ‏ ‏يُحَدِّثُ عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى الظُّهْرَ ‏ ‏بِذِي الْحُلَيْفَةِ ‏ ‏ثُمَّ دَعَا ‏ ‏بِبَدَنَتِهِ ‏ ‏أَوْ أُتِيَ ‏ ‏بِبَدَنَتِهِ ‏ ‏فَأَشْعَرَ ‏ ‏صَفْحَةَ ‏ ‏سَنَامِهَا الْأَيْمَنِ ثُمَّ ‏ ‏سَلَتَ ‏ ‏الدَّمَ عَنْهَا ‏ ‏وَقَلَّدَهَا ‏ ‏بِنَعْلَيْنِ ثُمَّ أَتَى ‏ ‏رَاحِلَتَهُ ‏ ‏فَلَمَّا قَعَدَ عَلَيْهَا ‏ ‏وَاسْتَوَتْ ‏ ‏بِهِ عَلَى ‏ ‏الْبَيْدَاءِ ‏ ‏أَهَلَّ ‏ ‏بِالْحَجِّ ‏","","",""],[2183,2183,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ بْنُ يَزِيدَ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَبِي الْعَالِيَةِ الرِّيَاحِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ عَمِّ نَبِيِّكُمْ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَعْنِي ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَدْعُو بِهَذِهِ الدَّعَوَاتِ عِنْدَ ‏ ‏الْكَرْبِ ‏ ‏لَا إِلَهَ إِلَّا اللَّهُ الْعَلِيمُ الْعَظِيمُ لَا إِلَهَ إِلَّا اللَّهُ رَبُّ الْعَرْشِ الْعَظِيمِ لَا إِلَهَ إِلَّا اللَّهُ رَبُّ السَّمَاوَاتِ السَّبْعِ وَرَبُّ الْعَرْشِ الْكَرِيمِ ‏","","",""],[2184,2184,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا الْعَالِيَةِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ عَمِّ نَبِيِّكُمْ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَبَهْزٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏أَخْبَرَنِي ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَبِي الْعَالِيَةِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏ابْنُ عَمِّ نَبِيِّكُمْ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا يَنْبَغِي لِعَبْدٍ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏عَبْدٍ ‏ ‏فِي أَنْ يَقُولَ أَنَا خَيْرٌ مِنْ ‏ ‏يُونُسَ بْنِ مَتَّى ‏ ‏وَنَسَبَهُ إِلَى أَبِيهِ ‏","","",""],[2185,2185,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو بِشْرٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سَعِيدَ بْنَ جُبَيْرٍ ‏ ‏يُحَدِّثُ عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ خَالَتَهُ ‏ ‏أُمَّ حُفَيْدٍ ‏ ‏أَهْدَتْ إِلَى ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَمْنًا وَأَضُبًّا ‏ ‏وَأَقِطًا ‏ ‏قَالَ ‏ ‏فَأَكَلَ مِنْ السَّمْنِ وَمِنْ ‏ ‏الْأَقِطِ ‏ ‏وَتَرَكَ الْأَضُبَّ تَقَذُّرًا ‏ ‏فَأُكِلَ عَلَى مَائِدَةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلَوْ كَانَ حَرَامًا لَمْ يُؤْكَلْ عَلَى مَائِدَةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قُلْتُ مَنْ قَالَ لَوْ كَانَ حَرَامًا قَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏","","",""],[2186,2186,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏عَمْرُو بْنُ دِينَارٍ ‏ ‏أَنْبَأَنِي ‏ ‏طَاوُسٌ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏أُمِرْتُ أَنْ أَسْجُدَ عَلَى سَبْعَةٍ وَلَا ‏ ‏أَكُفَّ ‏ ‏شَعَرًا وَلَا ثَوْبًا ‏ ‏ثُمَّ ‏ ‏قَالَ ‏ ‏مَرَّةً أُخْرَى أُمِرَ نَبِيُّكُمْ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يَسْجُدَ عَلَى سَبْعٍ وَلَا ‏ ‏يَكُفَّ ‏ ‏شَعَرًا وَلَا ثَوْبًا ‏","","",""],[2187,2187,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏يُوسُفَ بْنِ مِهْرَانَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ ‏ ‏جِبْرِيلَ ‏ ‏قَالَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّهُ قَدْ ‏ ‏حُبِّبَ إِلَيْكَ الصَّلَاةُ فَخُذْ مِنْهَا مَا شِئْتَ ‏","","",""],[2188,2188,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْأَحْوَصِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏سِمَاكٌ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏قَالَ قَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏أُتِيتُ وَأَنَا نَائِمٌ فِي رَمَضَانَ فَقِيلَ لِي إِنَّ اللَّيْلَةَ لَيْلَةُ الْقَدْرِ قَالَ فَقُمْتُ وَأَنَا نَاعِسٌ فَتَعَلَّقْتُ بِبَعْضِ ‏ ‏أَطْنَابِ ‏ ‏فُسْطَاطِ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَتَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَإِذَا هُوَ ‏ ‏يُصَلِّي فَنَظَرْتُ فِي تِلْكَ اللَّيْلَةِ فَإِذَا هِيَ لَيْلَةُ ثَلَاثٍ وَعِشْرِينَ ‏","","",""],[2189,2189,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏ثَابِتٌ يَعْنِي ابْنَ يَزِيدَ ‏ ‏حَدَّثَنَا ‏ ‏هِلَالٌ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَبِيتُ اللَّيَالِي الْمُتَتَابِعَةَ ‏ ‏طَاوِيًا ‏ ‏وَأَهْلُهُ لَا يَجِدُونَ عَشَاءً قَالَ وَكَانَ عَامَّةُ خُبْزِهِمْ خُبْزَ الشَّعِيرِ ‏","","",""],[2190,2190,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ كَثِيرٍ أَبُو دَاوُدَ الْوَاسِطِيُّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ شِهَابٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي سِنَانٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏خَطَبَنَا ‏ ‏يَعْنِي رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا أَيُّهَا النَّاسُ ‏ ‏كُتِبَ عَلَيْكُمْ الْحَجُّ قَالَ فَقَامَ ‏ ‏الْأَقْرَعُ بْنُ حَابِسٍ ‏ ‏فَقَالَ فِي كُلِّ عَامٍ يَا رَسُولَ اللَّهِ قَالَ لَوْ قُلْتُهَا لَوَجَبَتْ وَلَوْ وَجَبَتْ لَمْ تَعْمَلُوا بِهَا ‏ ‏أَوْ لَمْ تَسْتَطِيعُوا أَنْ تَعْمَلُوا بِهَا ‏ ‏فَمَنْ زَادَ فَهُوَ تَطَوُّعٌ ‏","","",""],[2191,2191,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏طَافَ سَبْعًا وَطَافَ سَعْيًا وَإِنَّمَا سَعَى أَحَبَّ أَنْ يُرِيَ النَّاسَ قُوَّتَهُ ‏","","",""],[2192,2192,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ الْهَاشِمِيُّ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو زُبَيْدٍ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏مِقْسَمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏صَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمِنًى ‏ ‏يَوْمَ التَّرْوِيَةِ ‏ ‏الظُّهْرَ ‏","","",""],[2193,2193,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَمْنَعْ أَحَدُكُمْ أَخَاهُ ‏ ‏مِرْفَقَهُ ‏ ‏أَنْ يَضَعَهُ عَلَى جِدَارِهِ ‏","","",""],[2194,2194,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنِ ‏ ‏ابْنِ هُبَيْرَةَ ‏ ‏عَنْ ‏ ‏مَيْمُونٍ الْمَكِّيِّ ‏ ‏أَنَّهُ رَأَى ‏ ‏ابْنَ الزُّبَيْرِ عَبْدَ اللَّهِ ‏ ‏وَصَلَّى بِهِمْ يُشِيرُ بِكَفَّيْهِ حِينَ يَقُومُ وَحِينَ يَرْكَعُ وَحِينَ يَسْجُدُ وَحِينَ يَنْهَضُ لِلْقِيَامِ فَيَقُومُ فَيُشِيرُ بِيَدَيْهِ قَالَ فَانْطَلَقْتُ إِلَى ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏فَقُلْتُ لَهُ إِنِّي قَدْ رَأَيْتُ ‏ ‏ابْنَ الزُّبَيْرِ ‏ ‏صَلَّى صَلَاةً لَمْ أَرَ أَحَدًا يُصَلِّيهَا فَوَصَفَ لَهُ هَذِهِ الْإِشَارَةَ فَقَالَ إِنْ أَحْبَبْتَ أَنْ تَنْظُرَ إِلَى صَلَاةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَاقْتَدِ بِصَلَاةِ ‏ ‏ابْنِ الزُّبَيْرِ ‏","","",""],[2195,2195,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ زَكَرِيَّا ‏ ‏عَنْ ‏ ‏دَاوُدَ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَتْ ‏ ‏قُرَيْشٌ ‏ ‏لِلْيَهُودِ ‏ ‏أَعْطُونَا شَيْئًا نَسْأَلُ عَنْهُ هَذَا الرَّجُلَ فَقَالُوا سَلُوهُ عَنْ الرُّوحِ فَسَأَلُوهُ فَنَزَلَتْ ‏ { ‏وَيَسْأَلُونَكَ عَنْ الرُّوحِ قُلْ الرُّوحُ مِنْ أَمْرِ رَبِّي وَمَا أُوتِيتُمْ مِنْ الْعِلْمِ إِلَّا قَلِيلًا ‏} ‏قَالُوا أُوتِينَا عِلْمًا كَثِيرًا أُوتِينَا التَّوْرَاةَ وَمَنْ أُوتِيَ التَّوْرَاةَ فَقَدْ أُوتِيَ خَيْرًا كَثِيرًا قَالَ فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏ { ‏قُلْ لَوْ كَانَ الْبَحْرُ مِدَادًا لِكَلِمَاتِ رَبِّي لَنَفِدَ الْبَحْرُ ‏}","","",""],[2196,2196,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدِ بْنِ أَبِي شَيْبَةَ ‏ ‏وَسَمِعْتُهُ ‏ ‏أَنَا مِنْ ‏ ‏ابْنِ أَبِي شَيْبَةَ ‏ ‏قَالَ ثَنَا ‏ ‏ابْنُ مُبَارَكٍ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِلْأَسْلَمِيِّ ‏ ‏لَعَلَّكَ قَبَّلْتَ أَوْ لَمَسْتَ أَوْ نَظَرْتَ ‏","","",""],[2197,2197,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدِ بْنِ أَبِي شَيْبَةَ ‏ ‏وَسَمِعْتُهُ ‏ ‏أَنَا مِنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَرَادَ أَنْ يَخْرُجَ إِلَى سَفَرٍ قَالَ ‏ ‏اللَّهُمَّ أَنْتَ الصَّاحِبُ فِي السَّفَرِ ‏ ‏وَالْخَلِيفَةُ ‏ ‏فِي الْأَهْلِ اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ ‏ ‏الضُّبْنَةِ ‏ ‏فِي السَّفَرِ وَالْكَآبَةِ فِي ‏ ‏الْمُنْقَلَبِ ‏ ‏اللَّهُمَّ اطْوِ لَنَا الْأَرْضَ وَهَوِّنْ عَلَيْنَا السَّفَرَ وَإِذَا أَرَادَ الرُّجُوعَ قَالَ ‏ ‏آيِبُونَ ‏ ‏تَائِبُونَ عَابِدُونَ لِرَبِّنَا حَامِدُونَ وَإِذَا دَخَلَ أَهْلَهُ قَالَ تَوْبًا تَوْبًا لِرَبِّنَا ‏ ‏أَوْبًا ‏ ‏لَا ‏ ‏يُغَادِرُ ‏ ‏عَلَيْنَا ‏ ‏حَوْبًا ‏","","",""],[2198,2198,"","","‏ ‏وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيَقْرَأَنَّ الْقُرْآنَ أَقْوَامٌ مِنْ أُمَّتِي ‏ ‏يَمْرُقُونَ ‏ ‏مِنْ الْإِسْلَامِ كَمَا ‏ ‏يَمْرُقُ ‏ ‏السَّهْمُ مِنْ ‏ ‏الرَّمِيَّةِ ‏","","",""],[2199,2199,"","","‏ ‏وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَسْتَقْبِلُوا وَلَا ‏ ‏تُحَفِّلُوا ‏ ‏وَلَا ‏ ‏يَنْعِقْ ‏ ‏بَعْضُكُمْ لِبَعْضٍ ‏","","",""],[2200,2200,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدٍ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ بْن أَحْمَد ‏ ‏وَسَمِعْتُهُ ‏ ‏مِنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدَةُ بْنُ سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏يَعْقُوبَ بْنِ عُتْبَةَ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَدَّقَ ‏ ‏أُمَيَّةَ ‏ ‏فِي شَيْءٍ مِنْ شِعْرِهِ فَقَالَ ‏ ‏رَجُلٌ وَثَوْرٌ تَحْتَ رِجْلِ يَمِينِهِ ‏ ‏وَالنَّسْرُ لِلْأُخْرَى وَلَيْثٌ ‏ ‏مُرْصَدُ ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَدَقَ وَقَالَ ‏ ‏وَالشَّمْسُ تَطْلُعُ كُلَّ آخِرِ لَيْلَةٍ ‏ ‏حَمْرَاءَ يُصْبِحُ لَوْنُهَا ‏ ‏يَتَوَرَّدُ ‏ ‏تَأْبَى فَمَا تَطْلُعْ لَنَا فِي ‏ ‏رِسْلِهَا ‏ ‏إِلَّا مُعَذَّبَةً وَإِلَّا ‏ ‏تُجْلَدُ ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَدَقَ ‏","","",""]];
